import type { ActionErrorCode, ActionErrorParams, ActionResult } from './action-result'

export class ActionFailureError extends Error {
  constructor(readonly code: ActionErrorCode, readonly params?: ActionErrorParams) {
    super(code)
    this.name = 'ActionFailureError'
  }
}

/**
 * Converts an expected action failure into a returned code. Anything else is a
 * programming error and keeps propagating, so it still shows up in server logs.
 */
export async function runAction<T>(fn: () => Promise<T | ActionResult<T>>): Promise<ActionResult<T>> {
  try {
    return await fn() as ActionResult<T>
  } catch (error) {
    if (error instanceof ActionFailureError) return { error: error.code, params: error.params }
    throw error
  }
}

// Apps a workspace can allow or block for its bots (N4 允许使用的应用). Pure: shared by UI, store and tests.
// GitHub and Linear are not here: bots do not reach them through a per-app tool, so a switch would do nothing.
import { z } from 'zod'
import { TOOLKIT_SLUG } from '@/lib/composio-accounts'

export const POLICY_APPS = ['gmail', 'googlecalendar', 'slack', 'notion'] as const
export type PolicyApp = (typeof POLICY_APPS)[number]
/** Backend catalog may expand before the settings page adopts its new rows. */
export const POLICY_TOOLKIT_IDS = [...POLICY_APPS, 'googledrive'] as const
export type PolicyToolkitId = (typeof POLICY_TOOLKIT_IDS)[number]
export const APP_ACCESS = ['allow', 'deny'] as const
export type AppAccess = (typeof APP_ACCESS)[number]

/** Any store app can be turned off for a workspace's bots, not only the rows the settings page lists. */
export const setAppPolicyInput = z.object({ app: z.string().regex(TOOLKIT_SLUG), access: z.enum(APP_ACCESS) }).strict()

/** The personal write tools (lib/operations/model-write-tools) and the app each one writes to. */
export const WRITE_TOOL_APPS: Record<string, PolicyApp> = {
  append_notion_paragraph: 'notion',
  send_slack_message: 'slack',
  cancel_calendar_event: 'googlecalendar',
}

export const isPolicyApp = (value: string): value is PolicyToolkitId => (POLICY_TOOLKIT_IDS as readonly string[]).includes(value)

/** What a blocked tool call returns to the model: a plain error code, as other tool failures do. */
export const APP_BLOCKED = { error: 'integrationBlockedByWorkspace' } as const

// oxlint-disable-next-line no-restricted-imports -- the one place that schedules after() work
import { after } from 'next/server'
import { AsyncLocalStorage } from 'node:async_hooks'
import { waitUntil } from '@vercel/functions'
import { context } from '@opentelemetry/api'
import { runJob, type JobKind } from '@/lib/tracing/jobs'

// Work that outlives its request, labelled as its own job for tracing and the
// db_sample log (docs/operations/tracing.md, "Background work").

/** A fixed job name, never ids or user data: `after:<job>` or `cron:<route>/<part>`. */
export type JobLabel = `after:${string}` | `cron:${string}`

export type AfterJobOptions = {
  /** Outside a request (a script, a test) run the work now, kept alive with waitUntil, instead of throwing as after() does. */
  orRun?: boolean
  /**
   * Keep the scheduling call's async context (its request database scope) even
   * when the scheduler invokes the work from another context, as
   * AsyncLocalStorage.bind does. The job's label is entered inside the bound
   * function, so it still wins over the scheduling request's.
   */
  retainContext?: boolean
  /** Test seam for next/server's after(). */
  schedule?: (task: () => unknown) => void
}

const kindOf = (label: JobLabel): JobKind => (label.startsWith('cron:') ? 'cron' : 'background')

/**
 * next/server's after(), with the deferred work run as its own job: a child
 * span named `label`, under the request that scheduled it, with that label
 * as `mikka.route` and `mikka.client_kind` `background` (`cron` for `cron:`).
 *
 * after() runs its callback in a snapshot of the scheduling request's async
 * context (Next's bindSnapshot), so without this the work's queries would
 * carry the request's route, under a request span that has already ended.
 * runJob is entered inside that callback, after the snapshot is restored, so
 * its label is the one in force when the work runs. Do not bind `task` itself
 * with AsyncLocalStorage.bind/snapshot (entering it would restore the
 * request's context over the label); use `retainContext` instead.
 */
export function afterJob(label: JobLabel, task: () => unknown, { orRun = false, retainContext = false, schedule = after }: AfterJobOptions = {}): void {
  const parent = context.active()
  const job = () => context.with(parent, () => runJob(label, kindOf(label), task, { detach: true }))
  const run = retainContext ? AsyncLocalStorage.bind(job) : job
  try { schedule(run) } catch (error) {
    if (!orRun) throw error
    let pending: unknown
    try { pending = run() } catch { return }
    waitUntil(Promise.resolve(pending).catch(() => {}))
  }
}

/** Wraps a cron route handler, so its queries carry `cron:<name>` and `mikka.client_kind=cron` inside the request span. */
export function cronJob<A extends unknown[], R>(name: string, handler: (...args: A) => R): (...args: A) => R {
  return (...args) => runJob(`cron:${name}`, 'cron', () => handler(...args))
}

// Hosted-model (Mikka 默认) usage, card verification and the points balance,
// as the backend reports them (#531, #558, #559), and the UI's helpers for them.

/** Every state `getHostedUsage` reports; a refused model call carries the same code. */
export const HOSTED_STATES = ['ready', 'verification_required', 'free_allowance_used', 'points_exhausted', 'platform_paused', 'usage_in_progress', 'usage_concurrency_limit', 'usage_cost_unavailable'] as const
export type HostedState = (typeof HOSTED_STATES)[number]
export type HostedRefusal = Exclude<HostedState, 'ready'>

export interface HostedBalance {
  /** A verified card, a paid plan or a purchase. */
  verified: boolean
  /** Remaining one-off allowance, integer microdollars (USD 1 = 1,000,000). */
  free: number
  /** Remaining purchased points, converted to microdollars. */
  purchased: number
}

export interface HostedUsage {
  state: HostedState
  balance: HostedBalance
  /** A personal workspace: card verification (the person's, C19) lands here. */
  personal?: boolean
  /** The person has a Claude / ChatGPT subscription connected; it serves them in any workspace (#838). */
  subscribed?: boolean
  /** No card and nothing bought: the free messages left (TRIAL_MESSAGES); null otherwise. */
  trialLeft?: number | null
  /** The workspace this was read for, so a dialog opened from the chat acts there. */
  workspaceId?: string
}

/** #558 `cardVerificationStatus`. */
export interface CardVerificationStatus {
  status: 'unverified' | 'pending' | 'verified' | 'unavailable'
  last4?: string | null
  /** Whether this card granted the allowance, or it was already claimed by another workspace. */
  allowance?: 'granted' | 'claimed_elsewhere' | null
}

/** #559 `getCreditBilling`: one balance (allowance included at 100 points per dollar) and 账单记录. */
export interface CreditTransaction {
  id: string
  date: string
  type: 'topup' | 'verification' | 'refund'
  points: number
  amountCents: number | null
  currency: string | null
  stripeFeeCents: number | null
  status: 'succeeded'
  receiptUrl: string | null
}

export interface CreditBillingView {
  balancePoints: number
  transactions: CreditTransaction[]
}

/** #559 `startPointsPurchase` accepts only these USD amounts. */
export const POINTS_PURCHASE_AMOUNTS = [10, 25, 50] as const
export const POINTS_PER_USD = 100
const MICRO_USD_PER_POINT = 10_000

/**
 * The refusal code in a model failure, or null. Failure records carry the code
 * as the whole message or inside a longer one (`Error: verification_required`).
 */
export function hostedRefusal(message: string | null | undefined): HostedRefusal | null {
  if (!message) return null
  const match = /\b(verification_required|free_allowance_used|points_exhausted|platform_paused|usage_in_progress|usage_concurrency_limit|usage_cost_unavailable)\b/.exec(message)
  return match ? match[1] as HostedRefusal : null
}

/**
 * What the refusal line above the composer offers, from the person's real
 * state (`usage`, null until read). With a subscription connected it serves
 * them in every workspace (#838), so a refusal is a moment's outage: 暂时不可用
 * and 重试. 连接订阅 only with none connected; 验证银行卡 in a personal workspace
 * with no verified card (C19); 打开计费 in a team with no points. Nothing until
 * the state is read.
 */
export function refusalOffer(code: HostedRefusal, usage: HostedUsage | null) {
  const busy = code === 'usage_in_progress' || code === 'usage_concurrency_limit' || code === 'usage_cost_unavailable'
  // A team with no points of its own: retrying never helps, even with a subscription connected. Its 计费 page buys points or turns on a member's shared credits.
  const billing = !busy && usage?.personal === false && (code === 'verification_required' || code === 'free_allowance_used' || code === 'points_exhausted')
  const transient = busy || (Boolean(usage?.subscribed) && !billing)
  return {
    transient,
    billing,
    card: !transient && Boolean(usage?.personal) && (code === 'verification_required' || (usage?.balance.verified === false && (code === 'free_allowance_used' || code === 'points_exhausted'))),
    connect: !transient && usage?.subscribed === false,
    // A personal workspace with a verified card that ran out: 充值 right there (decision 2026-11-02-1450).
    topUp: !transient && Boolean(usage?.personal) && usage?.balance.verified === true && (code === 'free_allowance_used' || code === 'points_exhausted'),
  }
}

/** Allowance and purchased points as one balance, rounded down so the screen never shows more than is left. */
export function balancePoints(balance: HostedBalance): number {
  return Math.floor(Math.max(0, balance.free + balance.purchased) / MICRO_USD_PER_POINT)
}

import { z } from 'zod'

// What the plugins page shows for a Composio connected account, and the few
// rules around it, kept free of the SDK so they can be tested on their own.

export const COMPOSIO_APP_IDS = ['gmail', 'googlecalendar', 'notion', 'slack'] as const
export type ComposioAppId = (typeof COMPOSIO_APP_IDS)[number]
/** Backend catalog. The legacy four-app UI keeps its own presentation list. */
export const COMPOSIO_TOOLKIT_IDS = [...COMPOSIO_APP_IDS, 'googledrive'] as const
export type ComposioToolkitId = (typeof COMPOSIO_TOOLKIT_IDS)[number]

/**
 * Composio statuses that are not an account the person has: a link that was
 * opened and never finished (INITIALIZING, INITIATED) or one that was already
 * disconnected (REVOKED).
 */
const HIDDEN_STATUSES = new Set(['INITIALIZING', 'INITIATED', 'REVOKED'])

export type ConnectedAccountView<Toolkit extends string = ComposioAppId> = {
  id: string
  toolkit: Toolkit
  /** Composio status: ACTIVE, INACTIVE, EXPIRED or FAILED once hidden ones are dropped. */
  status: string
  /** Composio's own switch (`isDisabled`). Disabled accounts are skipped by actions and triggers. */
  enabled: boolean
  alias: string | null
  createdAt: string
  /** The provider's email, read once when the account was connected. */
  email: string | null
  /** The account bots use for this toolkit (see `pickDefaultAccountId`). */
  isDefault: boolean
}

type ComposioAccountLike = {
  id: string
  status: string
  isDisabled: boolean
  alias?: string | null
  createdAt: string
  toolkit: { slug: string }
}

/** A Composio toolkit slug as the catalog lists them (lower case, digits, `_`). */
export const TOOLKIT_SLUG = /^[a-z][a-z0-9_]{0,63}$/
export const isToolkitSlug = (value: unknown): value is string => typeof value === 'string' && TOOLKIT_SLUG.test(value)
/** Mikka's own integrations. The store and account lists show ours, never a Composio copy of them. */
export const OWN_INTEGRATIONS: ReadonlySet<string> = new Set(['github', 'linear', 'telegram'])

/**
 * The account as the page shows it, or null when its toolkit is malformed or
 * one of Mikka's own integrations, or it is not a real account yet. Only these fields leave the server; credentials in
 * `state` and `data` never do.
 */
export function toConnectedAccountView(account: ComposioAccountLike): ConnectedAccountView<string> | null {
  if (!isToolkitSlug(account.toolkit.slug) || OWN_INTEGRATIONS.has(account.toolkit.slug) || HIDDEN_STATUSES.has(account.status)) return null
  const alias = account.alias?.trim() || null
  return { id: account.id, toolkit: account.toolkit.slug, status: account.status, enabled: !account.isDisabled, alias, createdAt: account.createdAt, email: null, isDefault: false }
}

type DefaultCandidate = { id: string; status: string; isDisabled: boolean; createdAt: string }

/**
 * The account bots use for one toolkit: the one the person chose with 设为默认
 * while it is usable (ACTIVE and on). With no choice, a sole usable account
 * is unambiguous; otherwise require a selection rather than changing identity.
 */
export function pickDefaultAccountId(accounts: DefaultCandidate[], chosenId: string | null | undefined) {
  const usable = accounts.filter(account => account.status === 'ACTIVE' && !account.isDisabled)
  if (chosenId) return usable.some(account => account.id === chosenId) ? chosenId : null
  return usable.length === 1 ? usable[0].id : null
}

export type ComposioAccountRecord = {
  accountId: string
  toolkit?: string
  email: string | null
  /** The provider was asked for the email (found or not), so it is not asked again. */
  emailChecked: boolean
  /** The last time the provider was asked, final answer or not; null when never. */
  lastAttemptAt: Date | null
  isDefault: boolean
  /** The provider refused the person's authorization while Composio still lists the account as ACTIVE. */
  needsReconnect?: boolean
}

/**
 * Adds what Mikka stores (email, chosen default) to the accounts Composio
 * listed. An account the provider refused shows as Composio's own EXPIRED,
 * so the list offers the same reconnect it gives an expired one.
 */
export function withAccountRecords(accounts: ConnectedAccountView<string>[], records: ComposioAccountRecord[]): ConnectedAccountView<string>[] {
  const byId = new Map(records.map(record => [record.accountId, record]))
  const defaults = new Map<string, string | null>()
  for (const app of new Set(accounts.map(account => account.toolkit))) {
    const own = accounts.filter(account => account.toolkit === app)
    const chosen = records.find(record => record.isDefault && (record.toolkit === app || own.some(account => account.id === record.accountId)))?.accountId
    defaults.set(app, pickDefaultAccountId(own.map(account => ({ ...account, isDisabled: !account.enabled })), chosen))
  }
  return accounts.map(account => ({
    ...account,
    ...(account.status === 'ACTIVE' && byId.get(account.id)?.needsReconnect ? { status: 'EXPIRED' } : {}),
    email: byId.get(account.id)?.email ?? null,
    isDefault: defaults.get(account.toolkit) === account.id,
  }))
}

const EMAIL = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/

/** A plain, lower-cased email address, or null for anything else. */
export function sanitizeEmail(value: unknown): string | null {
  if (typeof value !== 'string') return null
  const email = value.trim().toLowerCase()
  return email.length <= 254 && EMAIL.test(email) ? email : null
}

function field(value: unknown, ...path: string[]): unknown {
  let current = value
  for (const key of path) {
    if (!current || typeof current !== 'object') return undefined
    current = (current as Record<string, unknown>)[key]
  }
  return current
}

/**
 * Where each provider says who the account is, read through Composio's proxy
 * with the account's own token. Slack needs two calls: auth.test for the user
 * id, then users.info for that user's email (needs users:read.email).
 */
export const PROVIDER_IDENTITY: Record<ComposioToolkitId, { endpoint: string; headers?: Record<string, string>; email: (data: unknown) => unknown }> = {
  googledrive: { endpoint: 'https://www.googleapis.com/drive/v3/about?fields=user(emailAddress)', email: data => field(data, 'user', 'emailAddress') },
  gmail: { endpoint: 'https://gmail.googleapis.com/gmail/v1/users/me/profile', email: data => field(data, 'emailAddress') },
  // The primary calendar's id is the account's email address.
  googlecalendar: { endpoint: 'https://www.googleapis.com/calendar/v3/calendars/primary', email: data => field(data, 'id') },
  notion: { endpoint: 'https://api.notion.com/v1/users/me', headers: { 'Notion-Version': '2022-06-28' }, email: data => field(data, 'bot', 'owner', 'user', 'person', 'email') },
  slack: { endpoint: 'https://slack.com/api/auth.test', email: data => field(data, 'user_id') },
}

/** The provider could not give a final answer (429, 5xx, 401…); ask again later. */
export class ComposioEmailLookupError extends Error {
  constructor(readonly status: number) {
    super(`Provider answered ${status}`)
    this.name = 'ComposioEmailLookupError'
  }
}

/**
 * Only a successful HTTP response is a final answer. In particular, Google
 * also uses 403 for temporary quota failures, so it cannot mean "no email".
 * Failures are retried after the caller's cooldown.
 */
export function providerAnswer(status: number, data: unknown): unknown {
  if (status >= 200 && status < 300) return data
  throw new ComposioEmailLookupError(status)
}

/** Slack reports API errors inside HTTP 200. Never cache one as "no email". */
export function slackAnswer(data: unknown): unknown {
  if (field(data, 'ok') !== true) throw new ComposioEmailLookupError(200)
  return data
}

export const SLACK_USER_INFO = 'https://slack.com/api/users.info'
export const slackUserEmail = (data: unknown) => field(data, 'user', 'profile', 'email')
export const slackUserId = (value: unknown) => typeof value === 'string' && /^[UW][A-Z0-9]{2,20}$/.test(value) ? value : null

/**
 * A path in this app to come back to after Composio's connect page, without
 * the base path: same origin, not an API route, at most 512 characters.
 * Hash dropped. Null when the value is anything else.
 */
export function safeReturnPath(value: unknown): string | null {
  if (typeof value !== 'string' || value.length > 512 || !value.startsWith('/') || value.startsWith('//') || value.includes('\\') || [...value].some(char => char.charCodeAt(0) < 0x20)) return null
  let url: URL
  try { url = new URL(value, 'https://mikka.invalid') } catch { return null }
  if (url.origin !== 'https://mikka.invalid' || /^\/(?:[a-z]{2}(?:-[A-Z]{2})?\/)?api(?:\/|$)/.test(url.pathname)) return null
  return `${url.pathname}${url.search}`
}



/** Connect and reconnect both go to Composio's hosted connect page, over HTTPS. */
export function composioConnectRedirect(value: unknown): URL | null {
  if (typeof value !== 'string') return null
  try {
    const url = new URL(value)
    return url.protocol === 'https:' && url.hostname === 'connect.composio.dev' ? url : null
  } catch {
    return null
  }
}


export const accountAliasSchema = z.string().trim().min(1).max(60)

export const accountUpdateSchema = z.union([
  z.object({ accountId: z.string().trim().min(1).max(255), enabled: z.boolean() }).strict(),
  z.object({ accountId: z.string().trim().min(1).max(255), alias: accountAliasSchema }).strict(),
  z.object({ accountId: z.string().trim().min(1).max(255), default: z.literal(true) }).strict(),
])

/** Composio refuses an alias another of the person's accounts on that toolkit already has. */
export function isDuplicateAliasError(error: unknown) {
  if (!error || typeof error !== 'object') return false
  const { status, message } = error as { status?: unknown; message?: unknown }
  return status === 409 || (typeof message === 'string' && /alias/i.test(message) && /(unique|already|exist|duplicate|taken|conflict)/i.test(message))
}

/** Complete the person's explicit disconnect before forgetting local metadata.
 * No HTTP-status-based fallback may choose another destructive operation. */
export async function disconnectAndForgetAccount(deps: {
  disconnect: () => Promise<unknown>
  forget: () => Promise<unknown>
}) {
  await deps.disconnect()
  await deps.forget()
}

import { createHash } from 'node:crypto'
import { z } from 'zod'
import type { UserModelMessage } from 'ai'

export const MAX_USER_IMAGES = 2
export const MAX_USER_IMAGE_BYTES = 1024 * 1024
export const MAX_PERSONAL_SUBMISSION_BYTES = 3 * 1024 * 1024
export const userImageInputSchema = z.strictObject({ dataUrl: z.string().max(Math.ceil(MAX_USER_IMAGE_BYTES / 3) * 4 + 64) })
export type UserImageInput = z.infer<typeof userImageInputSchema>
export interface StoredUserImage { dataUrl: string; mediaType: 'image/png' | 'image/jpeg' | 'image/webp'; byteLength: number; sha256: string }
function normalize(image: UserImageInput): StoredUserImage {
  const match = /^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/]+={0,2})$/.exec(image.dataUrl)
  if (!match || match[2].length % 4 !== 0) throw new Error('userImageInvalid')
  const bytes = Buffer.from(match[2], 'base64')
  if (!bytes.length || bytes.length > MAX_USER_IMAGE_BYTES || bytes.toString('base64') !== match[2]) throw new Error('userImageInvalid')
  const type = match[1] as StoredUserImage['mediaType']
  if (!(type === 'image/png' ? bytes.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10])) : type === 'image/jpeg' ? bytes.subarray(0,3).equals(Buffer.from([255,216,255])) : bytes.subarray(0,4).toString() === 'RIFF' && bytes.subarray(8,12).toString() === 'WEBP')) throw new Error('userImageInvalid')
  return { dataUrl: image.dataUrl, mediaType: type, byteLength: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') }
}
export const userImageInputsSchema = z.array(userImageInputSchema).max(MAX_USER_IMAGES).superRefine((images, context) => {
  for (const [index,image] of images.entries()) {
    try { normalize(image) } catch { context.addIssue({ code:'custom',message:'userImageInvalid',path:[index] }) }
  }
})
/** Called only after the host authenticates the submitting user. No URLs are fetched. */
export function normalizeUserImages(input: unknown): StoredUserImage[] {
  return input === undefined ? [] : userImageInputsSchema.parse(input).map(normalize)
}
const storedImageSchema = z.strictObject({ dataUrl:userImageInputSchema.shape.dataUrl,mediaType:z.enum(['image/png','image/jpeg','image/webp']),byteLength:z.number().int().positive().max(MAX_USER_IMAGE_BYTES),sha256:z.string().regex(/^[a-f0-9]{64}$/) })
/** Read only from the stored host user_message event, never from peer/tool prose. */
export function userImageContent(input: unknown): Extract<UserModelMessage['content'], unknown[]> {
  if (input === undefined) return []
  const images = z.array(storedImageSchema).max(MAX_USER_IMAGES).parse(input)
  return images.map(stored => {
    const actual = normalize({dataUrl:stored.dataUrl})
    if (actual.sha256 !== stored.sha256 || actual.mediaType !== stored.mediaType || actual.byteLength !== stored.byteLength) throw new Error('storedUserImageInvalid')
    return { type:'file' as const,data:actual.dataUrl,mediaType:actual.mediaType }
  })
}

import { Pool, type PoolClient, type QueryResult } from 'pg'
import { AsyncLocalStorage } from 'node:async_hooks'

type Effect = () => void | Promise<void>
type State = { active: boolean; effects: Map<string, Effect>; savepoints: { name: string; effects: Map<string, Effect> }[]; scope: object }
const STATE = Symbol.for('mikka.database.commitEffects')
/** Request proxies expose only the executor used for commit observation. */
export const COMMIT_EXECUTOR = Symbol.for('mikka.database.commitExecutor')
const COMMIT_CONTEXT = Symbol.for('mikka.database.commitContext')
type ObservedClient = PoolClient & { [STATE]?: State }
const pools = new WeakSet<Pool>()

const reset = (state: State) => { state.active = false; state.effects.clear(); state.savepoints = [] }
const run = (effect: Effect) => {
  // A best-effort invalidation cannot turn a successful COMMIT into a failed write.
  try { Promise.resolve(effect()).catch(() => console.warn('[live] committed invalidation failed')) }
  catch { console.warn('[live] committed invalidation failed') }
}

/** Attach before BEGIN, below the existing device-authority wrapper. No SQL is added. */
export function observeCommitEffects(client: PoolClient, scope: object = client) {
  const observed = client as ObservedClient
  if (observed[STATE]) { observed[STATE].scope = scope; return }
  const state: State = { active: false, effects: new Map(), savepoints: [], scope }
  observed[STATE] = state
  const query = client.query.bind(client) as (...args: unknown[]) => unknown
  const settled = (text: string, result: unknown) => {
    const command = text.trim().replace(/;$/, '').trim()
    const results = (Array.isArray(result) ? result : [result]) as QueryResult[]
    const last = results.at(-1)?.command
    if (/^(?:begin|start\s+transaction)\b/i.test(command)) {
      reset(state); state.active = true
    } else if (/^(?:commit|end)(?:\s|$)/i.test(command)) {
      const effects = last === 'COMMIT' ? [...state.effects.values()] : []
      reset(state)
      if (/\band\s+chain$/i.test(command)) state.active = true
      for (const effect of effects) run(effect)
    } else {
      const rollback = command.match(/^rollback\s+to\s+(?:savepoint\s+)?("(?:[^"]|"")+"|[\w]+)$/i)
      const release = command.match(/^release\s+(?:savepoint\s+)?("(?:[^"]|"")+"|[\w]+)$/i)
      const savepoint = command.match(/^savepoint\s+("(?:[^"]|"")+"|[\w]+)$/i)
      const name = (raw: string) => raw.startsWith('"') ? raw.slice(1, -1).replaceAll('""', '"') : raw.toLowerCase()
      if (rollback || release) {
        const wanted = name((rollback ?? release)![1])
        const index = state.savepoints.findLastIndex(point => point.name === wanted)
        if (index >= 0) {
          if (rollback) state.effects = new Map(state.savepoints[index].effects)
          state.savepoints.length = index + (rollback ? 1 : 0)
        }
      } else if (/^(?:rollback|abort)(?:\s|$)/i.test(command)) {
        reset(state)
        if (/\band\s+chain$/i.test(command)) state.active = true
      } else if (savepoint) {
        state.savepoints.push({ name: name(savepoint[1]), effects: new Map(state.effects) })
      }
    }
  }
  ;(client as { query: unknown }).query = (...args: unknown[]) => {
    const first = args[0]
    const text = typeof first === 'string' ? first : (first as { text?: unknown } | null)?.text
    if (typeof text !== 'string') return query(...args)
    const failed = () => { if (/^\s*(?:commit|end)\b/i.test(text)) reset(state) }
    const callback = args.at(-1)
    if (typeof callback === 'function') {
      return query(...args.slice(0, -1), (error: unknown, result: unknown) => {
        if (error) failed(); else settled(text, result)
        return callback(error, result)
      })
    }
    const pending = query(...args)
    return pending instanceof Promise ? pending.then(result => { settled(text, result); return result }, error => { failed(); throw error }) : pending
  }
}

export function observePoolCommits(pool: Pool) {
  if (pools.has(pool)) return
  pools.add(pool)
  pool.on('connect', client => observeCommitEffects(client, pool))
  pool.on('acquire', client => observeCommitEffects(client, pool))
  pool.on('release', (_error, client) => { const state = (client as ObservedClient)[STATE]; if (state) reset(state) })
}

export function hasCommitEffect(client: PoolClient, key: string) {
  return (client as ObservedClient)[STATE]?.effects.has(key) ?? false
}

/** Only explicit writers register effects. Reads and rolled-back savepoints send nothing. */
export function afterCommit(client: PoolClient, key: string, effect: Effect) {
  const state = (client as ObservedClient)[STATE]
  if (!state) throw new Error('Commit effects require an observed database client')
  // COMMIT can be issued after the originating request context has exited.
  const committed = AsyncLocalStorage.bind(effect)
  if (state.active) state.effects.set(key, committed)
  else run(committed) // An autocommitted write has already succeeded.
}

/** The pinned node-postgres Drizzle transaction holds the same observed client
 * for every nested savepoint. Register below Drizzle, not after a nested
 * transaction callback, which can return before the outer COMMIT. */
export function afterDatabaseCommit(executor: object, key: string, effect: Effect) {
  const client = commitExecutor(executor)
  const context = (executor as { [COMMIT_CONTEXT]?: ReturnType<typeof AsyncLocalStorage.snapshot> })[COMMIT_CONTEXT] ?? AsyncLocalStorage.snapshot()
  const committed = () => context(effect)
  if ((client as ObservedClient)[STATE]) afterCommit(client as PoolClient, key, committed)
  else if (client instanceof Pool) run(committed) // The caller has awaited its autocommitted statement.
  else throw new Error('Commit effects require an observed node-postgres executor')
}

/** A service retaining a bound query must retain its executor and request
 * context at the same instant. Later callbacks cannot guess its transaction,
 * database or device authority from the query function. */
export function captureDatabaseQuery(executor: Pick<Pool | PoolClient, 'query'>) {
  return { query: AsyncLocalStorage.bind(executor.query.bind(executor)),
    [COMMIT_EXECUTOR]: commitExecutor(executor), [COMMIT_CONTEXT]: AsyncLocalStorage.snapshot() }
}

/** Opaque identity only: batching cannot mix requests to separate databases. */
export function databaseCommitScope(executor: object): object {
  const client = commitExecutor(executor)
  const scope = (client as ObservedClient)[STATE]?.scope
  if (scope) return scope
  if (client instanceof Pool) return client
  throw new Error('Commit effects require an observed node-postgres executor')
}

function commitExecutor(executor: object): ObservedClient | Pool {
  const client = ((executor as { session?: { client?: unknown } }).session?.client ?? executor) as ObservedClient | Pool
  return (client as { [COMMIT_EXECUTOR]?: ObservedClient | Pool })[COMMIT_EXECUTOR] ?? client
}

import { previewDatabaseURL } from '../../scripts/preview-database-url.mjs'

export function mikkaDatabaseURL(env: Record<string, string | undefined>) {
  return env.VERCEL_ENV === 'preview' ? previewDatabaseURL(env) : env.MIKKA_DATABASE_URL
}

export function workspaceDatabaseURL(env: Record<string, string | undefined>) {
