import { AsyncLocalStorage } from 'node:async_hooks'
import { COMMIT_EXECUTOR } from '../db/commit-effects'
import { currentRoute } from '../tracing/labels'
import { isLiveRevisionKind, LIVE_ID } from '../live/events'
import type { LiveScope } from '../live/scope'
import { liveRevisionKey, readLiveRevisions, type LiveRef, type LiveRevisions } from '../live/revisions'
import { readBatchOwnerRevisionKinds, type BatchReadAction } from './read-batch-contract'

type Database = Parameters<typeof readLiveRevisions>[0]
type RevisionRead = { ref: LiveRef; resolve: (revision: number | undefined) => void; reject: (error: unknown) => void }
type RevisionQueue = { values: Map<string, Promise<number | undefined>>; pending: Map<string, RevisionRead>; scheduled: boolean }
type BatchContext = {
  active: boolean
  owners: Map<object, Map<string, Promise<LiveScope | null>>>
  revisions: Map<Database, RevisionQueue>
  subscriptionPolicies: Map<object, Map<string, Promise<boolean>>>
  ownerRevisionKinds: ReturnType<typeof readBatchOwnerRevisionKinds>
}
const batches = new AsyncLocalStorage<BatchContext>()

/** Installed only by the bounded read action. Detached after-work cannot keep
 * using the batch's authority/revision observations once its items settle. */
export async function withReadBatchContext<T>(work: () => Promise<T>, actions: readonly BatchReadAction[] = []): Promise<T> {
  const scope: BatchContext = { active: true, owners: new Map(), revisions: new Map(), subscriptionPolicies: new Map(), ownerRevisionKinds: readBatchOwnerRevisionKinds(actions) }
  try { return await batches.run(scope, work) }
  finally { scope.active = false; scope.owners.clear(); scope.revisions.clear(); scope.subscriptionPolicies.clear() }
}

/** Chat model readers consult the same workspace policy for keys and subscriptions.
 * Share only its observation in this read batch; each consumer keeps its own
 * data and authority checks. A request proxy must name its actual executor.
 * Deferred jobs have their own observation even while the parent is active. */
export function readBatchSubscriptionPolicy(database: object, workspaceId: string, read: () => Promise<boolean>): Promise<boolean> {
  const scope = batches.getStore()
  if (!scope?.active || /^(?:after|cron|workflow):/.test(currentRoute() ?? '')) return read()
  const executor = (database as { [COMMIT_EXECUTOR]?: object })[COMMIT_EXECUTOR] ?? database
  let policies = scope.subscriptionPolicies.get(executor)
  if (!policies) { policies = new Map(); scope.subscriptionPolicies.set(executor, policies) }
  let pending = policies.get(workspaceId)
  if (!pending) { pending = Promise.resolve().then(read); policies.set(workspaceId, pending) }
  return pending
}

export function readBatchOwnerScope(database: object, ownerId: string, read: () => Promise<LiveScope | null>): Promise<LiveScope | null> {
  const scope = batches.getStore()
  if (!scope?.active) return read()
  let owners = scope.owners.get(database)
  if (!owners) { owners = new Map(); scope.owners.set(database, owners) }
  let pending = owners.get(ownerId)
  if (!pending) { pending = Promise.resolve().then(read); owners.set(ownerId, pending) }
  return pending
}

/** A prepared batch already knows its owner-list kinds, but never their home.
 * Once the original reader resolves that home, read those counters together.
 * Later readers keep the conservative earlier values; only this reader's
 * original refs leave the helper. Missing/failed counters remain no proof. */
export async function readBatchOwnerRevisions(database: Database, refs: readonly LiveRef[], home?: LiveScope | null): Promise<LiveRevisions> {
  const scope = batches.getStore()
  if (!scope?.active || !home || !scope.ownerRevisionKinds.length) return readBatchRevisions(database, refs)
  const requested = new Set(refs.filter(ref => isLiveRevisionKind(ref.kind) && LIVE_ID.test(ref.id))
    .map(ref => liveRevisionKey(ref.kind, ref.id.toLowerCase())))
  // An entity read or another home cannot start this owner's list prefetch.
  if (!scope.ownerRevisionKinds.some(kind => requested.has(liveRevisionKey(kind, home.workspaceId.toLowerCase()))))
    return readBatchRevisions(database, refs)
  const values = await readBatchRevisions(database, [...refs, ...scope.ownerRevisionKinds.map(kind => ({ kind, id: home.workspaceId }))])
  return Object.fromEntries(Object.entries(values).filter(([key]) => requested.has(key)))
}

/** Each caller still awaits the revision before its data. Keys arriving in the
 * same microtask share one SQL statement; already observed keys keep the older
 * value, never a newer revision that could acknowledge unseen data. */
export async function readBatchRevisions(database: Database, refs: readonly LiveRef[]): Promise<LiveRevisions> {
  const scope = batches.getStore()
  if (!scope?.active) return readLiveRevisions(database, refs)
  let queue = scope.revisions.get(database)
  if (!queue) { queue = { values: new Map(), pending: new Map(), scheduled: false }; scope.revisions.set(database, queue) }
  const selected = new Map<string, Promise<number | undefined>>()
  for (const ref of refs) {
    if (!isLiveRevisionKind(ref.kind) || !LIVE_ID.test(ref.id)) continue
    const id = ref.id.toLowerCase(), key = liveRevisionKey(ref.kind, id)
    let value = queue.values.get(key)
    if (!value) {
      value = new Promise<number | undefined>((resolve, reject) => { queue!.pending.set(key, { ref: { kind: ref.kind, id }, resolve, reject }) })
      queue.values.set(key, value)
    }
    selected.set(key, value)
  }
  if (queue.pending.size && !queue.scheduled) {
    queue.scheduled = true
    const waiting = queue
    queueMicrotask(() => {
      const reads = [...waiting.pending]
      waiting.pending.clear(); waiting.scheduled = false
      void readLiveRevisions(database, reads.map(([, value]) => value.ref)).then(
        values => { for (const [key, value] of reads) value.resolve(values[key]) },
        error => { for (const [, value] of reads) value.reject(error) },
      )
    })
  }
  const observed = await Promise.all([...selected].map(async ([key, value]) => [key, await value] as const))
  return Object.fromEntries(observed.filter((entry): entry is readonly [string, number] => entry[1] !== undefined))
}

/** Only the Native transport coalesces these existing reads. Their original
 * authorization and any ordinary first-use initialization still apply. */
export const READ_BATCH_ACTION = 'desktop.readBatch'
export const MAX_READ_BATCH = 16
export const READ_BATCH_ACTIONS = [
  'issues.syncIssueList',
  'projects.listProjects',
  'teams.listTeams',
  'team-relations.listProjectTeams',
  'task-runs.pollTaskRuns',
  'task-runs.syncThreadList',
  'coordinator.pollBotChatSummaries',
  'bots.pollBots',
  'coordinator.syncCoordinatorChat',
] as const

export type BatchReadAction = typeof READ_BATCH_ACTIONS[number]
const reads: ReadonlySet<string> = new Set(READ_BATCH_ACTIONS)
export function isBatchReadAction(action: unknown): action is BatchReadAction {
  return typeof action === 'string' && reads.has(action)
}

/** Only these existing readers observe an owner-home revision. Entity and
 * selected-team keys still wait for their original reader's authorization. */
const ownerRevisionKinds = {
  'issues.syncIssueList': 'issue_list',
  'task-runs.pollTaskRuns': 'task_run_list',
  'task-runs.syncThreadList': 'thread_list',
  'coordinator.pollBotChatSummaries': 'bot_chat_list',
} as const

export function readBatchOwnerRevisionKinds(actions: readonly BatchReadAction[]) {
  return [...new Set(actions.flatMap(action => Object.hasOwn(ownerRevisionKinds, action)
    ? [ownerRevisionKinds[action as keyof typeof ownerRevisionKinds]] : []))]
}

export type ReadBatchCall = { action: BatchReadAction; args: unknown[] }
export type ReadBatchItem = { ok: true; result: unknown } | { ok: false; status: number; error: { code: string } }

import { channel } from 'node:diagnostics_channel'
import { ActionFailureError } from '../action-error'
import { WorkspaceError } from '../workspace-error'
import { withRpcActionLog } from '../request-log'
import type { DesktopActions } from './handler'
import { isBatchReadAction, MAX_READ_BATCH, type ReadBatchCall, type ReadBatchItem } from './read-batch-contract'
import { withReadBatchContext } from './read-batch-context'

const actionErrors = channel('mikka.request.error')

/** The transport schema validates the whole envelope before invoking this
 * action. Resolve and parse every original action again before executing any
 * item, so batching never skips a reader's argument or ownership checks. */
export function createReadBatch(registry: () => DesktopActions) {
  return async (calls: ReadBatchCall[]): Promise<ReadBatchItem[]> => {
    if (!Array.isArray(calls) || calls.length < 1 || calls.length > MAX_READ_BATCH) throw new TypeError('desktop_rpc_request_invalid')
    const actions = registry()
    const prepared = calls.map(call => {
      if (!call || !isBatchReadAction(call.action) || !Object.hasOwn(actions, call.action)) throw new TypeError('desktop_rpc_request_invalid')
      const action = actions[call.action], args = action.args.safeParse(call.args)
      if (!args.success) throw new TypeError('desktop_rpc_request_invalid', { cause: args.error })
      if (!Array.isArray(args.data)) throw new TypeError('desktop_rpc_request_invalid')
      return { name: call.action, action, args: args.data as never[] }
    })
    return withReadBatchContext(async () => {
      let authFailure: ActionFailureError | undefined
      const items = await Promise.all(prepared.map(({ name, action, args }) => withRpcActionLog<ReadBatchItem>(name, async () => {
        try {
          const result = await action.invoke(args)
          // Cached-list actions preserve expected failures as ActionResult.
          // A revoked identity must still reach Main as the ordinary HTTP 401.
          if (result && typeof result === 'object' && 'error' in result && result.error === 'authRequired') throw new ActionFailureError('authRequired')
          return { ok: true, result }
        } catch (error) {
          try { actionErrors.publish(error) } catch { /* diagnostics cannot change the reader's result */ }
          if (error instanceof ActionFailureError) {
            if (error.code === 'authRequired') authFailure ??= error
            return { ok: false, status: error.code === 'authRequired' ? 401 : 400, error: { code: error.code } }
          }
          if (error instanceof WorkspaceError) return { ok: false, status: 403, error: { code: 'workspaceAccessDenied' } }
          return { ok: false, status: 500, error: { code: 'desktop_rpc_failed' } }
        }
      }, item => item.ok ? 200 : item.status)))
      // All item work and diagnostics settle before the request's identity and
      // batch-only memo are released, including when a reader rejects auth.
      if (authFailure) throw authFailure
      return items
    }, prepared.map(item => item.name))
  }
}

import { AsyncLocalStorage } from 'node:async_hooks'

export const DESKTOP_SESSION_CACHE_HEADER = 'x-mikka-session-cache'
type CacheResponse = { authorization: string; cache?: string }
const responseCache = new AsyncLocalStorage<CacheResponse>()

/** SDK output only, bound to this request's bearer. This is never a session
 * identity or an authorization cache, and is never part of request logs. */
export function recordNativeSessionCache(headers: Headers | undefined, cache: string): void {
  const scope = responseCache.getStore()
  if (scope && headers?.get('authorization') === scope.authorization) scope.cache = cache
}

/** REST readers also need the SDK's replacement proof when it expires; without
 * this transport every later REST read would repeat the same session lookup. */
export function withNativeSessionCache<T extends Response>(headers: Headers, work: () => T | Promise<T>): Promise<T> {
  const authorization = headers.get('authorization')
  if (headers.get('x-mikka-client') !== 'desktop' || !authorization) return Promise.resolve(work())
  const scope: CacheResponse = { authorization }
  return responseCache.run(scope, async () => {
    const response = await work()
    // Explicit RPC rotation/clearing takes precedence over an earlier SDK read.
    if (scope.cache !== undefined && !response.headers.has(DESKTOP_SESSION_CACHE_HEADER)) response.headers.set(DESKTOP_SESSION_CACHE_HEADER, scope.cache)
    return response
  })
}

import { afterJob } from '@/lib/background'
import { setTimeout as delay } from 'node:timers/promises'
import { deviceGatewayEndpoint } from './device-gateway-client'
import { afterDatabaseCommit } from './db/commit-effects'
import { DEVICE_WORK_CHANNEL, notifyChannel } from './db/listen'
import { gatewayConfig } from './builtin-gateway/config'

/** Wakes this device's waiting commands long poll (the gateway-down fallback).
 * Sent with each gateway wake: with the gateway configured, every write that
 * gives a device work reaches notifyDeviceWork, so the long poll may wait on
 * LISTEN (lib/device-link.ts deviceWorkSubscription). */
async function notifyLongPoll(deviceId: string) {
  try {
    const { pool, withoutDatabaseClient } = await import('./db/request-scope')
    await withoutDatabaseClient(() => notifyChannel(pool, DEVICE_WORK_CHANNEL, [deviceId]))
  } catch { console.warn('[device-gateway] long poll notification failed', { deviceId }) }
}

/** A wake is idempotent; retry transient failures without dropping committed work. */
async function sendWake(deviceId: string, endpoint: NonNullable<ReturnType<typeof deviceGatewayEndpoint>>) {
  if (endpoint.mode === 'builtin') {
    try { const { builtinGateway } = await import('./builtin-gateway/runtime'); await builtinGateway()?.hub.work(deviceId) }
    catch { console.warn('[device-gateway] builtin work notification failed', { deviceId }) }
    return
  }
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt) await delay(attempt * 250)
    try {
      const response = await fetch(endpoint.url, {
        method: 'POST', headers: { authorization: `Bearer ${endpoint.secret}` },
        redirect: 'error', signal: AbortSignal.timeout(3_000),
      })
      await response.body?.cancel()
      if (response.ok) return
      if (response.status < 500 && response.status !== 429) break
    } catch { /* retry the signal; never send the work or credential to logs */ }
  }
  console.warn('[device-gateway] work notification failed', { deviceId })
}

/**
 * Call only after the owning transaction commits. after() keeps the signal
 * alive after the HTTP response; it is not a transaction commit hook (nested
 * after callbacks can start immediately). Work stays in authorized routes.
 * Non-Next hosts use the platform's waitUntil lifecycle instead.
 */
export function notifyDeviceWork(deviceId: string | null | undefined) {
  if (!deviceId) return
  const endpoint = deviceGatewayEndpoint(deviceId, 'push')
  if (!endpoint) return
  afterJob('after:device-wake', async () => { await Promise.all([sendWake(deviceId, endpoint), notifyLongPoll(deviceId)]) }, { orRun: true })
}

/** The outer Factory/Skill transaction has committed before this lookup. */
export async function notifyQueuedLocalRun(database: {
  query: (text: string, values: unknown[]) => Promise<{ rows: { deviceId: string }[] }>
}, userId: string, runId: string) {
  if (!gatewayConfig()) return
  try {
    const { rows: [run] } = await database.query(`SELECT r."deviceId" FROM agent_runs r
      JOIN devices d ON d.id=r."deviceId" AND d."ownerId"=r."userId"
      WHERE r.id=$1 AND r."userId"=$2 AND r.status='queued' AND r."stopRequestedAt" IS NULL
        AND d.kind='local' AND d.enabled=true AND d."removedAt" IS NULL`, [runId, userId])
    notifyDeviceWork(run?.deviceId)
  } catch { console.warn('[device-gateway] queued run notification failed', { runId }) }
}

export type RunControlTarget = { runIds: readonly string[] } | { userId: string } | { workspaceId: string }
const ACTIVE_RUN_STATUSES = ['preparing', 'running', 'paused', 'waiting_input', 'finishing']

/**
 * Wakes each device (local or cloud) holding one of these runs, so its daemon
 * checks run control again at once (#1212). A daemon on the gateway runs no
 * periodic check, so every write that can stop, pause or revoke a run, or
 * change its policy, calls this after commit. The wake makes current daemons
 * consume persisted stop/pause commands. Legacy daemons also refresh their
 * cached control state; current provider and tool calls need no remote check.
 */
export async function notifyRunControl(database: {
  query: (text: string, values: unknown[]) => Promise<{ rows: { deviceId: string }[] }>
}, target: RunControlTarget) {
  if (!gatewayConfig()) return
  if ('runIds' in target && target.runIds.length === 0) return
  const [where, values]: [string, unknown[]] = 'runIds' in target ? ['r.id=ANY($1::uuid[])', [[...target.runIds]]]
    : 'userId' in target ? ['r."userId"=$1 AND r.status=ANY($2::text[])', [target.userId, ACTIVE_RUN_STATUSES]]
      : ['r."botId" IN (SELECT id FROM bots WHERE "workspaceId"=$1) AND r.status=ANY($2::text[])', [target.workspaceId, ACTIVE_RUN_STATUSES]]
  try {
    const { rows } = await database.query(`SELECT DISTINCT r."deviceId" FROM agent_runs r
      JOIN devices d ON d.id=r."deviceId" AND d."ownerId"=r."userId"
      WHERE ${where}`, values)
    for (const { deviceId } of rows) notifyDeviceWork(deviceId)
  } catch { console.warn('[device-gateway] run control notification failed') }
}

/** notifyRunControl once this transaction commits; nothing on rollback. The
 * device lookup reads the committed rows from the default pool. */
export function runControlChanged(executor: object, target: RunControlTarget, lookup?: Parameters<typeof notifyRunControl>[0]) {
  if (!gatewayConfig()) return
  if ('runIds' in target && target.runIds.length === 0) return
  const key = 'runIds' in target ? `runs:${[...target.runIds].sort().join(',')}` : 'userId' in target ? `owner:${target.userId}` : `workspace:${target.workspaceId}`
  // A wake is best-effort: it can never fail the stop or policy write itself.
  try {
    afterDatabaseCommit(executor, `run-control:${key}`, async () => {
      if (lookup) return notifyRunControl(lookup, target)
      const { pool, withoutDatabaseClient } = await import('./db/request-scope')
      await withoutDatabaseClient(() => notifyRunControl(pool, target))
    })
  } catch { console.warn('[device-gateway] run control notification unavailable') }
}

import { afterDatabaseCommit } from './db/commit-effects'
import { wakeTokens, wakeTransport, workflowWakesEnabled } from './workflow-wake'

/**
 * Jobs whose work carries a persisted due time (#1212 D). Instead of a minute
 * sweep, one durable timer per job (workflows/due-timer) does the work when it
 * is due; a write that makes work due sooner wakes it after COMMIT, or starts
 * it when none runs. The job's cron route stays as a slow reconciliation sweep
 * that only recovers a start lost between COMMIT and here.
 */
export type DueKind = 'schedules' | 'run-recovery' | 'account-deletions' | 'audit-retention'
export type DueJob = { run(): Promise<number | null>; next(): Promise<number | null> }

export const dueJobs: Record<DueKind, DueJob> = {
  schedules: {
    run: async () => { const { sweepSchedules, scheduleNextDue } = await import('./schedules/runtime'); await sweepSchedules(); return scheduleNextDue() },
    next: async () => (await import('./schedules/runtime')).scheduleNextDue(),
  },
  'run-recovery': {
    // Only the sweeps due now run (#1371); a pass with nothing due costs one statement.
    run: async () => (await import('./run-recovery-due')).runRecoveryPass(),
    next: async () => (await import('./run-recovery-due')).runRecoveryNextDue(),
  },
  'account-deletions': {
    run: async () => {
      const [{ sweepAccountDeletions }, { cleanupChatFiles }] = await Promise.all([import('./account/deletion-jobs'), import('./chat-attachments/store')])
      await sweepAccountDeletions()
      await cleanupChatFiles()
      return accountDeletionsNextDue()
    },
    next: () => accountDeletionsNextDue(),
  },
  'audit-retention': {
    run: async () => {
      const [{ deliverWorkspaceAudits }, { sweepAuditRetention }] = await Promise.all([import('./audit/delivery'), import('./audit/retention')])
      await deliverWorkspaceAudits()
      await sweepAuditRetention()
      return auditRetentionNextDue()
    },
    next: () => auditRetentionNextDue(),
  },
}

async function accountDeletionsNextDue() {
  const [{ pool }, { nextAccountDeletionsDue }] = await Promise.all([import('./db'), import('./account-deletions-due')])
  return nextAccountDeletionsDue(pool)
}

async function auditRetentionNextDue() {
  const [{ pool }, { workspacePool }, { nextAuditRetentionDue }] = await Promise.all([import('./db'), import('./workspace-db'), import('./audit-retention-due')])
  return nextAuditRetentionDue(pool, workspacePool)
}

/** The run holding a timer's token, and the deployment it is pinned to. */
export type DueTimerHolder = { runId: string; deploymentId: string }

/** Tests replace the Workflow calls here to observe timer starts, lookups and cancels without a Workflow world. */
export const dueTimerTransport: {
  start?: (kind: DueKind) => Promise<unknown>
  holder?: (token: string) => Promise<DueTimerHolder | null>
  cancel?: (runId: string) => Promise<unknown>
} = {}

const ENDED = new Set(['completed', 'failed', 'cancelled'])

async function timerHolder(token: string): Promise<DueTimerHolder | null> {
  if (dueTimerTransport.holder) return dueTimerTransport.holder(token)
  const { getHookByToken } = await import('workflow/api')
  let runId: string
  try { ({ runId } = await getHookByToken(token)) } catch { return null }
  const { getWorld } = await import('workflow/runtime')
  const run = await (await getWorld()).runs.get(runId, { resolveData: 'none' })
  return ENDED.has(run.status) ? null : { runId, deploymentId: run.deploymentId }
}

async function startDueTimer(kind: DueKind) {
  if (dueTimerTransport.start) return dueTimerTransport.start(kind)
  const [{ start }, { dueTimer }] = await Promise.all([import('workflow/api'), import('@/workflows/due-timer/workflow')])
  return start(dueTimer, [kind])
}

/** A bounded machine Workflow may exit only after another durable owner has
 * accepted responsibility. Unlike a request's best-effort wake, a failed
 * handoff propagates so the Workflow step remains retryable. */
export async function handoffRunRecoveryTimer(): Promise<void> {
  if (!workflowWakesEnabled()) return
  if (process.env.VERCEL_ENV === 'production') {
    await (await import('./due-timer-owner')).armCurrentRecoveryTimer()
    return
  }
  if (await replaceStaleDueTimer('run-recovery')) return
  try {
    const resume = wakeTransport.resume ?? (await import('workflow/api')).resumeHook
    await resume(wakeTokens.dueTimer('run-recovery'), {})
  } catch {
    await startDueTimer('run-recovery')
  }
}

/** Production run recovery elects and hands over its own owner (lib/due-timer-owner.ts, #1403); it is never cancelled here. */
const ownsItsDeployment = (kind: DueKind) => kind === 'run-recovery' && process.env.VERCEL_ENV === 'production'

/** Kinds this process has seen held by a run on its own deployment; checked once per process. */
const current = new Set<DueKind>()

/**
 * A timer run is pinned to the deployment that started it and keeps that code
 * for its whole life (#1410). Every kind but production run recovery, which owns its handover (#1403): The first arm of each kind in a process on a newer
 * deployment cancels a run on another deployment and starts its successor here.
 * The successor's first pass does whatever came due meanwhile. True when it
 * replaced one. Workflow API calls only, no database.
 */
export async function replaceStaleDueTimer(kind: DueKind): Promise<boolean> {
  const deploymentId = process.env.VERCEL_DEPLOYMENT_ID
  if (!deploymentId || current.has(kind) || !workflowWakesEnabled() || ownsItsDeployment(kind)) return false
  const holder = await timerHolder(wakeTokens.dueTimer(kind))
  if (!holder) return false
  current.add(kind)
  if (holder.deploymentId === deploymentId) return false
  if (dueTimerTransport.cancel) await dueTimerTransport.cancel(holder.runId)
  else await (await import('workflow/api')).getRun(holder.runId).cancel({ cancelReason: `due timer replaced by deployment ${deploymentId}` })
  await startDueTimer(kind)
  return true
}

/** replaceStaleDueTimer for every kind; never throws. */
export async function replaceStaleDueTimers() {
  await Promise.all((Object.keys(dueJobs) as DueKind[]).map(kind => replaceStaleDueTimer(kind).catch(error => {
    console.error('Due timer replacement failed', { kind, name: error instanceof Error ? error.name : typeof error })
    return false
  })))
}

/** Tests only: forget which kinds this process already checked. */
export function forgetCheckedDueTimers() { current.clear() }

/** Wakes the job's running timer, or starts one. Best effort: the slow sweep re-arms a lost start. */
export async function armDueTimer(kind: DueKind): Promise<void> {
  if (!workflowWakesEnabled()) return
  if (kind === 'run-recovery' && process.env.VERCEL_ENV === 'production') {
    try { await (await import('./due-timer-owner')).armCurrentRecoveryTimer() }
    catch (error) {
      const { CodedError, logCodedError } = await import('@mikka/protocol/coded-error')
      // A guard has already emitted its closed metadata at the failed check.
      if (!(error instanceof CodedError && error.code === 'due_timer_owner_unavailable')) {
        logCodedError(new CodedError('due_timer_owner_unavailable', { detail: 'sdk_operation_failed', cause: error }), { kind, phase: 'arm' })
      }
    }
    return
  }
  try {
    if (await replaceStaleDueTimer(kind)) return
  } catch (error) {
    console.error('Due timer replacement failed', { kind, name: error instanceof Error ? error.name : typeof error })
  }
  try {
    const resume = wakeTransport.resume ?? (await import('workflow/api')).resumeHook
    await resume(wakeTokens.dueTimer(kind), {})
    return
  } catch { /* no timer holds the token: start one */ }
  try {
    await startDueTimer(kind)
  } catch (error) {
    console.error('Due timer start failed', { kind, name: error instanceof Error ? error.name : typeof error })
  }
}

/** armDueTimer after the current request, for a write that has already committed. */
export function armDueTimerSoon(kind: DueKind) {
  if (!workflowWakesEnabled()) return
  void import('./background').then(({ afterJob }) => afterJob('after:due-timer', () => armDueTimer(kind), { orRun: true })).catch(() => {})
}

/** armDueTimer once this transaction commits; nothing on rollback. Never fails the write. */
export function armDueTimerAfterCommit(executor: object, kind: DueKind) {
  if (!workflowWakesEnabled()) return
  try {
    afterDatabaseCommit(executor, `due-timer:${kind}`, async () => {
      const { afterJob } = await import('./background')
      afterJob('after:due-timer', () => armDueTimer(kind), { orRun: true })
    })
  } catch { /* an executor without commit tracking: the slow sweep re-arms */ }
}

import { CodedError } from '@mikka/protocol/coded-error'

export type MikkaEdition = 'community' | 'cloud'

/** The deployment edition is runtime configuration, never a browser build flag. */
export function getEdition(env: Readonly<Record<string, string | undefined>> = process.env): MikkaEdition {
  const value = env.MIKKA_EDITION?.trim() || 'community'
  if (value === 'community' || value === 'cloud') return value
  throw new CodedError('MIKKA_EDITION_INVALID', { detail: 'expected_community_or_cloud' })
}

export function isCloudEdition(env: Readonly<Record<string, string | undefined>> = process.env): boolean {
  return getEdition(env) === 'cloud'
}

import { latestDefaultCandidates } from './model-order-plan'

export interface ModelToggle { enabled: boolean; fresh: boolean; manual: boolean }
export interface ModelSettings { refreshedAt?: string | null; autoEnable: boolean; models: Record<string, ModelToggle> }

/** Same release/family selection as #1515; no second version parser. */
export function reconcileSubscriptionModels(ids: string[], previous?: ModelSettings | null): ModelSettings {
  const latest = new Set(latestDefaultCandidates(ids.map(model => ({ model, name: model,
    harness: 'claude_code' as const, source: { kind: 'subscription' as const, connectionId: 'catalogue' } }))).map(item => item.model))
  const autoEnable = previous?.autoEnable ?? true
  const models: Record<string, ModelToggle> = Object.create(null)
  // Retain choices for temporarily absent models, including explicit disabled choices.
  for (const [id, value] of Object.entries(previous?.models ?? {})) models[id] = value
  for (const id of ids) {
    const prior = previous?.models[id]
    models[id] = prior?.manual ? prior : { enabled: previous && !autoEnable ? prior?.enabled ?? false : latest.has(id), fresh: false, manual: false }
  }
  return { ...previous, autoEnable, models }
}

export function modelEnabled(settings: ModelSettings | null | undefined, id: string) {
  return settings?.models[id]?.enabled ?? true
}

import type { Pool, PoolClient } from 'pg'
import { isDeepStrictEqual } from 'node:util'
import { z } from 'zod'
import type { WorkerDefinitionSnapshot } from './agent-kit/worker'

/** Authority is host data, never a Decision/model argument. References only: no credentials. */
const resource = z.object({
  kind: z.enum(['device', 'api_key', 'subscription', 'e2b', 'mcp']), id: z.string().min(1), ownerId: z.string().min(1),
  access: z.enum(['owner', 'workspace_share']), revision: z.string().optional(),
  grantId: z.uuid().optional(), workspaceId: z.uuid().optional(),
})
const account = z.object({
  kind: z.enum(['api_key', 'subscription', 'native_login', 'local_device', 'e2b']),
  ownerId: z.string().min(1), resourceId: z.string().min(1),
  amount: z.enum(['provider_unknown', 'metered', 'not_applicable']),
})
export const executionIdentitySchema = z.object({
  version: z.literal(1), requester: z.string().min(1), botId: z.string().nullable(), botOwner: z.string().nullable(),
  executionPrincipal: z.string().min(1), workspaceId: z.string().nullable(), outputOwner: z.string().min(1),
  resourceBindings: z.array(resource), billingAccount: z.object({ model: account, runtime: account }),
  personalResourcePolicy: z.literal('requester_only'),
})
export type ExecutionIdentity = z.infer<typeof executionIdentitySchema>
type Query = Pick<Pool | PoolClient, 'query'>
type RunAuthority = { userId: string; botId: string | null; deviceId: string | null; agentDefinition: WorkerDefinitionSnapshot | null }

export class ExecutionIdentityError extends Error {
  constructor() { super('executionIdentityUnavailable'); this.name = 'ExecutionIdentityError' }
}
const denied = (): never => { throw new ExecutionIdentityError() }

/** Membership is in the workspace DB, not the application's DB. */
export async function executionMembersActive(workspaceId: string, users: string[], membership?: Query): Promise<boolean> {
  const query = membership ?? (await import('./workspace-db')).workspacePool
  const ids = [...new Set(users)]
  const { rows } = await query.query<{ userId: string }>(`SELECT "userId" FROM mikka_workspace_members
    WHERE "workspaceId"=$1 AND "userId"=ANY($2::text[]) AND status='active'`, [workspaceId, ids])
  return ids.every(id => rows.some(row => row.userId === id))
}

/** Used before selecting resources for a borrowed Bot. A Bot never lends its owner's computer or accounts. */
export async function executionBotScope(query: Query, requester: string, botId: string, membership?: Query) {
  const { rows: [bot] } = await query.query<{ ownerId: string | null; workspaceId: string }>('SELECT "ownerId","workspaceId" FROM bots WHERE id=$1 AND "archivedAt" IS NULL', [botId])
  if (!bot?.ownerId || !await executionMembersActive(bot.workspaceId, [requester, bot.ownerId], membership)) return denied()
  return { ownerId: bot.ownerId, workspaceId: bot.workspaceId }
}

/** Freeze only after the host selected a device/model and checked task access. Re-run at each authority boundary. */
export async function freezeExecutionIdentity(query: Query, run: RunAuthority, membership?: Query, workspaceHint?: string | null): Promise<ExecutionIdentity> {
  const definition = run.agentDefinition
  if (!definition || !run.deviceId) return denied()
  const bot = run.botId ? await executionBotScope(query, run.userId, run.botId, membership) : null
  const workspaceId = bot?.workspaceId ?? workspaceHint ?? null
  if (workspaceId && !bot && !await executionMembersActive(workspaceId, [run.userId], membership)) return denied()
  const { rows: [device] } = await query.query<{ ownerId: string; kind: string; enabled: boolean }>('SELECT "ownerId",kind,enabled FROM devices WHERE id=$1', [run.deviceId])
  if (!device?.enabled || device.ownerId !== run.userId) return denied()
  const resourceBindings: ExecutionIdentity['resourceBindings'] = [{ kind: 'device', id: run.deviceId, ownerId: device.ownerId, access: 'owner' }]
  if (definition.customMcp) {
    if (definition.customMcp.workspaceId !== workspaceId) return denied()
    const authority = await (await import('./plugins/workspace-mcp')).validateMcpAuthority(query, run.userId, definition.customMcp, membership).catch(() => denied())
    for (const grant of authority.servers) resourceBindings.push({ kind: 'mcp', id: grant.id, ownerId: grant.ownerId,
      access: grant.grantId ? 'workspace_share' : 'owner', revision: String(grant.revision),
      ...(grant.grantId ? { grantId: grant.grantId } : {}), ...(authority.workspaceId ? { workspaceId: authority.workspaceId } : {}),
    })
  }
  let model: ExecutionIdentity['billingAccount']['model'] = { kind: 'native_login', ownerId: run.userId, resourceId: run.deviceId, amount: 'provider_unknown' }
  if (definition.apiKey && definition.subscription) return denied()
  if (definition.apiKey) {
    const { rows: [key] } = await query.query<{ ownerId: string; shared: boolean }>(`SELECT k."ownerId", EXISTS (
      SELECT 1 FROM model_api_key_shares s WHERE s."keyId"=k.id AND s."workspaceId"=$2
      AND NOT EXISTS (SELECT 1 FROM workspace_personal_policies p WHERE p."workspaceId"=$2 AND NOT p.subscriptions)) AS shared
      FROM model_api_keys k WHERE k.id=$1`, [definition.apiKey.keyId, workspaceId])
    if (!key || (key.ownerId !== run.userId && (!workspaceId || !key.shared || !await executionMembersActive(workspaceId, [run.userId, key.ownerId], membership)))) return denied()
    resourceBindings.push({ kind: 'api_key', id: definition.apiKey.keyId, ownerId: key.ownerId, access: key.ownerId === run.userId ? 'owner' : 'workspace_share' })
    model = { kind: 'api_key', ownerId: key.ownerId, resourceId: definition.apiKey.keyId, amount: 'provider_unknown' }
  } else if (definition.subscription) {
    const { rows: [binding] } = await query.query<{ ownerId: string; workspaceId: string; revision: string; modelId: string; route: string; shared: boolean }>(`SELECT b."ownerId",b."workspaceId",b."connectionRevision"::text AS revision,b."modelId",b.route,
      EXISTS (SELECT 1 FROM workspace_subscription_shares s WHERE s."ownerId"=b."ownerId" AND s."workspaceId"=$2 AND s."allowOthers"
      AND NOT EXISTS (SELECT 1 FROM workspace_personal_policies p WHERE p."workspaceId"=$2 AND NOT p.subscriptions)) AS shared
      FROM byos_bindings b JOIN byos_connections c ON c.id=b."connectionId" AND c."ownerId"=b."ownerId"
      AND c.state='connected' AND NOT c.paused AND c.epoch=b."connectionRevision" WHERE b.id=$1`, [definition.subscription.bindingId, workspaceId])
    if (!binding || binding.modelId !== definition.subscription.modelId || binding.route !== definition.subscription.route ||
      (binding.ownerId !== run.userId && (!workspaceId || binding.workspaceId !== workspaceId || !binding.shared || !await executionMembersActive(workspaceId, [run.userId, binding.ownerId], membership)))) return denied()
    resourceBindings.push({ kind: 'subscription', id: definition.subscription.bindingId, ownerId: binding.ownerId, access: binding.ownerId === run.userId ? 'owner' : 'workspace_share', revision: binding.revision })
    model = { kind: 'subscription', ownerId: binding.ownerId, resourceId: definition.subscription.bindingId, amount: 'provider_unknown' }
  } else if (device.kind === 'cloud') return denied()
  if (device.kind === 'cloud') {
    const { rows: [key] } = await query.query(`SELECT 1 FROM user_e2b_keys WHERE "userId"=$1 UNION ALL SELECT 1 FROM workspace_e2b_keys WHERE "createdBy"=$1 LIMIT 1`, [run.userId])
    if (!key) return denied()
    resourceBindings.push({ kind: 'e2b', id: run.userId, ownerId: run.userId, access: 'owner' })
  }
  return { version: 1, requester: run.userId, botId: run.botId, botOwner: bot?.ownerId ?? null,
    executionPrincipal: run.userId, workspaceId, outputOwner: run.userId, resourceBindings,
    billingAccount: { model, runtime: { kind: device.kind === 'cloud' ? 'e2b' : 'local_device', ownerId: device.ownerId, resourceId: device.kind === 'cloud' ? run.userId : run.deviceId, amount: device.kind === 'cloud' ? 'provider_unknown' : 'not_applicable' } },
    personalResourcePolicy: 'requester_only' }
}

/** Existing historical runs stay explicitly unattributed; they gain no new sharing authority. */
export async function revalidateExecutionIdentity(query: Query, run: RunAuthority, membership?: Query): Promise<ExecutionIdentity | null> {
  const frozen = run.agentDefinition?.executionIdentity
  if (frozen === undefined) return null
  const parsed = executionIdentitySchema.safeParse(frozen)
  if (!parsed.success) return denied()
  const current = await freezeExecutionIdentity(query, run, membership, parsed.data.workspaceId)
  if (!isDeepStrictEqual(parsed.data, current)) return denied()
  return parsed.data
}

export async function executionIdentityForRun(query: Query, runId: string, userId?: string, membership?: Query): Promise<ExecutionIdentity | null> {
  const { rows: [run] } = await query.query<RunAuthority>('SELECT "userId","botId","deviceId","agentDefinition" FROM agent_runs WHERE id=$1', [runId])
  if (!run || (userId && run.userId !== userId)) return denied()
  return revalidateExecutionIdentity(query, run, membership)
}

/** Only the host's device handoff path calls this, after choosing another device owned by the same requester.
 * A dead source device need not be online. All non-device grants are checked again and retain their original identity. */
export async function rebindExecutionDevice(query: Query, run: RunAuthority, deviceId: string, membership?: Query): Promise<WorkerDefinitionSnapshot | null> {
  if (!run.agentDefinition?.executionIdentity) return run.agentDefinition
  const prior = executionIdentitySchema.parse(run.agentDefinition.executionIdentity)
  const next = await freezeExecutionIdentity(query, { ...run, deviceId }, membership, prior.workspaceId)
  const standing = (identity: ExecutionIdentity) => ({ requester: identity.requester, botId: identity.botId, botOwner: identity.botOwner,
    executionPrincipal: identity.executionPrincipal, workspaceId: identity.workspaceId, outputOwner: identity.outputOwner,
    resourceBindings: identity.resourceBindings.filter(binding => binding.kind !== 'device' && binding.kind !== 'e2b'),
    model: identity.billingAccount.model.kind === 'native_login' ? { ...identity.billingAccount.model, resourceId: null } : identity.billingAccount.model, runtimeOwner: identity.billingAccount.runtime.ownerId, personalResourcePolicy: identity.personalResourcePolicy })
  if (!isDeepStrictEqual(standing(prior), standing(next))) return denied()
  return { ...run.agentDefinition, executionIdentity: next }
}

/** The last authorization point before a provider call, after discovery/decision IO. */
export async function activeExecutionIdentity(query: Query, runId: string, userId: string, membership?: Query): Promise<ExecutionIdentity | null> {
  const { rows: [run] } = await query.query<RunAuthority & { status: string; stopRequestedAt: Date | null; leaseExpiresAt: Date | null }>(
    'SELECT "userId","botId","deviceId","agentDefinition",status,"stopRequestedAt","leaseExpiresAt" FROM agent_runs WHERE id=$1', [runId])
  if (!run || run.userId !== userId || run.stopRequestedAt || !['queued', 'preparing', 'running', 'waiting_input', 'finishing'].includes(run.status)) return denied()
  if (run.deviceId && run.status !== 'queued' && (!run.leaseExpiresAt || new Date(run.leaseExpiresAt).getTime() <= Date.now())) return denied()
  return revalidateExecutionIdentity(query, run, membership)
}

