import { BlockList, isIP } from 'node:net'

// The pure half of link previews: which addresses are private, and reading
// a page's Open Graph tags. lib/link-preview.ts does the fetching.

export interface LinkPreview {
  url: string
  host: string
  siteName: string | null
  title: string | null
  description: string | null
  image: string | null
  icon: string | null
}

const PRIVATE = new BlockList()
for (const [network, prefix] of [['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16], ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15], ['224.0.0.0', 3]] as const) PRIVATE.addSubnet(network, prefix, 'ipv4')
for (const [network, prefix] of [['::', 128], ['::1', 128], ['fc00::', 7], ['fe80::', 10], ['ff00::', 8]] as const) PRIVATE.addSubnet(network, prefix, 'ipv6')

/** Loopback, private, link-local and other non-public addresses. */
export function isPrivateAddress(address: string): boolean {
  const mapped = address.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/i)?.[1]
  if (mapped) return PRIVATE.check(mapped, 'ipv4')
  return PRIVATE.check(address, isIP(address) === 6 ? 'ipv6' : 'ipv4')
}

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' }
function decode(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, code: string) => {
    if (code[0] !== '#') return ENTITIES[code.toLowerCase()] ?? entity
    const point = code[1] === 'x' || code[1] === 'X' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10)
    return Number.isFinite(point) && point <= 0x10ffff ? String.fromCodePoint(point) : entity
  }).replace(/\s+/g, ' ').trim()
}

function attribute(tag: string, name: string): string | null {
  const match = tag.match(new RegExp(`\\s${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i'))
  return match ? decode(match[1] ?? match[2] ?? match[3] ?? '') : null
}

/** Reads the preview fields from a page's <head>. */
export function parsePreview(html: string, pageUrl: string): Omit<LinkPreview, 'url' | 'host'> {
  const end = html.search(/<\/head>/i)
  const head = end > 0 ? html.slice(0, end) : html
  const meta: Record<string, string> = {}
  for (const [tag] of head.matchAll(/<meta\b[^>]*>/gi)) {
    const key = (attribute(tag, 'property') ?? attribute(tag, 'name'))?.toLowerCase()
    const content = attribute(tag, 'content')
    if (key && content && !(key in meta)) meta[key] = content
  }
  let icon: string | null = null
  for (const [tag] of head.matchAll(/<link\b[^>]*>/gi)) {
    const rel = attribute(tag, 'rel')?.toLowerCase().split(/\s+/) ?? []
    if (rel.includes('icon') || rel.includes('apple-touch-icon')) { icon = attribute(tag, 'href'); if (rel.includes('icon')) break }
  }
  const absolute = (value: string | null | undefined) => {
    if (!value) return null
    try {
      const url = new URL(value, pageUrl)
      return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : null
    } catch { return null }
  }
  const titleTag = head.match(/<title[^>]*>([^<]*)<\/title>/i)?.[1]
  const title = meta['og:title'] ?? meta['twitter:title'] ?? (titleTag ? decode(titleTag) : null)
  return {
    siteName: meta['og:site_name'] ?? null,
    title: title || null,
    description: meta['og:description'] ?? meta['twitter:description'] ?? meta.description ?? null,
    image: absolute(meta['og:image'] ?? meta['og:image:url'] ?? meta['twitter:image']),
    icon: absolute(icon) ?? absolute('/favicon.ico'),
  }
}

export const LIVE_KINDS = ['thread_list', 'task_run_list', 'bot_chat_list', 'device_list', 'bot_chat', 'issue_list', 'bot_list', 'group_list', 'workspace_settings', 'computer_state', 'approved_writes', 'approved_write', 'pending_actions', 'factory_task', 'factory_issue', 'issue_document', 'artifact', 'issue_members', 'issue_relations', 'issue_threads', 'thread', 'run', 'coordinator_session', 'model_settings', 'group_chat', 'hosted_billing', 'pull_request_status', 'subagent_events', 'project_map'] as const
export type LiveKind = typeof LIVE_KINDS[number]
/** `rev` is a post-commit counter of this key (lib/live/revisions.ts), never content. */
export type LiveInvalidation = { kind: LiveKind; id: string; rev?: number }
export const LIVE_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
export const LIVE_CHANNEL = /^[a-f0-9]{64}$/
/** Kinds whose pushes carry a revision. A reader of one returns the same counter. */
export const LIVE_REVISION_KINDS = ['bot_chat', 'bot_chat_list', 'issue_list', 'thread', 'run', 'task_run_list', 'group_chat', 'thread_list', 'project_map'] as const satisfies readonly LiveKind[]
export type LiveRevisionKind = typeof LIVE_REVISION_KINDS[number]
export const isLiveRevisionKind = (kind: LiveKind): kind is LiveRevisionKind => (LIVE_REVISION_KINDS as readonly LiveKind[]).includes(kind)
/** Version 2 sockets ask with this query parameter; version 1 sockets get only `{kind, id}`. */
export const LIVE_REVISION_PARAM = 'revisions'
export const liveRevision = (value: unknown): value is number => typeof value === 'number' && Number.isSafeInteger(value) && value > 0

/** The wire format is an invalidation key, never business content. A version 2
 * key may add its revision; a version 1 client keeps rejecting a third field. */
export function liveInvalidation(value: unknown, revisions = false): LiveInvalidation | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const record = value as Record<string, unknown>
  const size = Object.keys(record).length
  if (typeof record.id !== 'string' || !LIVE_ID.test(record.id)) return null
  if (!LIVE_KINDS.includes(record.kind as LiveKind)) return null
  if (size === 2) return { kind: record.kind as LiveKind, id: record.id }
  if (!revisions || size !== 3 || !liveRevision(record.rev) || !isLiveRevisionKind(record.kind as LiveKind)) return null
  return { kind: record.kind as LiveKind, id: record.id, rev: record.rev }
}

export function liveInvalidations(value: unknown, revisions = false): LiveInvalidation[] | null {
  if (!Array.isArray(value) || value.length < 1 || value.length > 16) return null
  const events = value.map(event => liveInvalidation(event, revisions))
  return events.every((event): event is LiveInvalidation => event !== null) ? events : null
}

/** What a version 1 socket (or an older Worker) carries: the same keys, no revision. */
export const withoutRevisions = (events: readonly LiveInvalidation[]): LiveInvalidation[] => events.map(({ kind, id }) => ({ kind, id }))

/** Readiness describes this deployed Worker, not WebSocket liveness or action
 * authority. Unknown future names are ignored by older clients. Version 1 is
 * exactly what older clients accept; only a socket that asked gets version 2. */
export function liveReady(version: 1 | 2 = 1) {
  return version === 2
    ? { type: 'live_ready', version: 2, kinds: [...LIVE_KINDS], revisions: [...LIVE_REVISION_KINDS] }
    : { type: 'live_ready', version: 1, kinds: [...LIVE_KINDS] }
}

const kindNames = (value: unknown) => Array.isArray(value) && value.length <= 32
  && value.every(kind => typeof kind === 'string' && /^[a-z_]{1,64}$/.test(kind)) && new Set(value).size === value.length

/** The Worker's kinds, and the kinds whose keys carry a revision (none for version 1). */
export function liveReadiness(value: unknown): { kinds: LiveKind[]; revisions: LiveKind[] } | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const record = value as Record<string, unknown>
  const size = Object.keys(record).length
  if (record.type !== 'live_ready' || !kindNames(record.kinds)) return null
  if (!(record.version === 1 && size === 3) && !(record.version === 2 && size === 4 && kindNames(record.revisions))) return null
  const known = (names: unknown) => (names as string[]).filter((kind): kind is LiveKind => LIVE_KINDS.includes(kind as LiveKind))
  return { kinds: known(record.kinds), revisions: record.version === 2 ? known(record.revisions).filter(isLiveRevisionKind) : [] }
}

export function liveCapabilities(value: unknown): LiveKind[] | null {
  return liveReadiness(value)?.kinds ?? null
}

import type { PoolClient } from 'pg'
import { sql } from 'drizzle-orm'
import type { workspaceDb } from '../workspace-db'
import { afterDatabaseCommit } from '../db/commit-effects'
import { liveGatewayConfig, type LiveScope } from './scope'
import type { LiveInvalidation } from './events'
import { ownerLiveScope } from './owner-scope'

type Database = Pick<PoolClient, 'query'>
export type OwnerListKind = 'thread_list' | 'task_run_list' | 'bot_chat_list' | 'device_list'
export type WorkspaceListKind = 'issue_list' | 'bot_list' | 'group_list' | 'workspace_settings'
type ListKind = OwnerListKind | WorkspaceListKind | 'model_settings'
type Target = { scope: LiveScope; events: LiveInvalidation[] }

const target = (scope: LiveScope, kinds: readonly ListKind[]): Target => ({
  scope, events: [...new Set(kinds)].map(kind => ({ kind, id: scope.workspaceId })),
})

/** A list key contains its already-known scope ID, never the changed entity. */
export async function ownerListTargets(workspaceDatabase: Database, ownerId: string, kinds: readonly OwnerListKind[]): Promise<Target[]> {
  const scope = await ownerLiveScope(workspaceDatabase, ownerId)
  return scope ? [target(scope, kinds)] : []
}

async function workspaceScopes(workspaceDatabase: Database, workspaceId: string, owners: readonly string[] | null = null) {
  const { rows } = await workspaceDatabase.query<LiveScope>(
    `SELECT m."userId" AS "ownerId",w.id AS "workspaceId" FROM mikka_workspaces w
      JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m.status='active'
      WHERE w.id=$1 AND (w.kind='team' OR w."userId"=m."userId")
        AND ($2::text[] IS NULL OR m."userId"=ANY($2::text[]))`, [workspaceId, owners],
  )
  return rows
}

/** Both state and completed reply previews follow the run's persisted owner and tenant.
 * A reply preview changes threads only; it cannot refresh every board card. */
export async function runListTargets(database: Database, workspaceDatabase: Database, runId: string, previewOnly = false) {
  const { rows: [run] } = await database.query<{ userId: string; issueId: string | null }>(
    'SELECT "userId","issueId" FROM agent_runs WHERE id=$1', [runId],
  )
  if (!run) return []
  const { threadLiveReferences } = await import('./panels')
  const [reference] = await threadLiveReferences(database, workspaceDatabase, [runId], run.userId)
  return reference?.workspaceId ? [target({ ownerId: run.userId, workspaceId: reference.workspaceId },
    previewOnly || !run.issueId ? ['thread_list'] : ['thread_list', 'task_run_list'])] : []
}

type IssueScope = { id: string; userId: string; scope: string; workspaceId: string | null }

async function issueListScopes(workspaceDatabase: Database, issue: IssueScope): Promise<LiveScope[]> {
  return issue.workspaceId ? workspaceScopes(workspaceDatabase, issue.workspaceId) : []
}

/** A task invalidates only its immutable tenant's active members. */
export async function issueListTargets(database: Database, workspaceDatabase: Database, issueId: string, titleChanged = false): Promise<Target[]> {
  const { rows: [issue] } = await database.query<IssueScope>(`SELECT id,"userId",scope,"workspaceId" FROM issues WHERE id=$1 AND "ownershipState"='bound'`, [issueId])
  if (!issue) return []
  const scopes = await issueListScopes(workspaceDatabase, issue)
  const targets = scopes.map(scope => target(scope, ['issue_list']))
  if (titleChanged) {
    // These readers resolve task names, but do not display the task body.
    // Ordinary autosaves must not invalidate every member's chat/run summary.
    const { rows: owners } = await database.query<{ userId: string }>('SELECT DISTINCT "userId" FROM agent_runs WHERE "issueId"=$1', [issueId])
    if (issue.workspaceId) targets.push(...(await workspaceScopes(workspaceDatabase, issue.workspaceId, owners.map(owner => owner.userId))).map(scope => target(scope, ['task_run_list'])))
    for (const ownerId of new Set(scopes.map(scope => scope.ownerId))) targets.push(...await ownerListTargets(workspaceDatabase, ownerId, ['bot_chat_list']))
  }
  return mergeTargets(targets)
}

/** Only actual participants receive a private group's list invalidation. A
 * removed participant may receive the same known workspace list key to clear
 * that row; no group ID, new membership or message crosses the channel. */
export async function groupListTargets(database: Database, workspaceDatabase: Database, conversationId: string, removedUserId: string | null = null) {
  const { rows: [group] } = await database.query<{ workspaceId: string }>(
    `SELECT "workspaceId" FROM conversations WHERE id=$1 AND kind='group'`, [conversationId],
  )
  if (!group) return []
  const { rows } = await database.query<{ memberId: string }>(
    `SELECT "memberId" FROM conversation_members WHERE "conversationId"=$1 AND "memberType"='user'
      AND ("leftAt" IS NULL OR "memberId"=$2)`, [conversationId, removedUserId],
  )
  return (await workspaceScopes(workspaceDatabase, group.workspaceId, rows.map(row => row.memberId))).map(scope => target(scope, ['group_list']))
}

export async function botListTargets(database: Database, workspaceDatabase: Database, botId: string) {
  const { rows: [bot] } = await database.query<{ ownerId: string; workspaceId: string }>('SELECT "ownerId","workspaceId" FROM bots WHERE id=$1', [botId])
  if (!bot) return []
  const scopes = await workspaceScopes(workspaceDatabase, bot.workspaceId, [bot.ownerId])
  return mergeTargets([
    ...scopes.map(scope => target(scope, ['bot_list', 'thread_list', 'task_run_list'])),
    ...await ownerListTargets(workspaceDatabase, bot.ownerId, ['bot_chat_list']),
  ])
}

export async function workspaceListTargets(workspaceDatabase: Database, workspaceId: string, kinds: readonly WorkspaceListKind[]) {
  return (await workspaceScopes(workspaceDatabase, workspaceId)).map(scope => target(scope, kinds))
}

function mergeTargets(targets: readonly Target[]): Target[] {
  const merged = new Map<string, Target>()
  for (const value of targets) {
    const key = JSON.stringify(value.scope)
    let current = merged.get(key)
    if (!current) { current = { scope: value.scope, events: [] }; merged.set(key, current) }
    for (const event of value.events) if (!current.events.some(existing => existing.kind === event.kind && existing.id === event.id)) current.events.push(event)
  }
  return [...merged.values()]
}

type Resolve = (database: Database, workspaceDatabase: Database) => Promise<Target[]>

/** Register at the real writer. A nested savepoint or held query wrapper does
 * not publish before the outer COMMIT, and deferred reads retain its database. */
async function changed(executor: object, key: string, resolve: Resolve) {
  if (!liveGatewayConfig(process.env)) return
  const { scheduleLive } = await import('./notify')
  afterDatabaseCommit(executor, `list:${key}`, () => scheduleLive(async () => {
    const { pool, withoutDatabaseClient } = await import('../db/request-scope')
    const { workspacePool } = await import('../workspace-db')
    await withoutDatabaseClient(async () => {
      const targets = mergeTargets(await resolve(pool, workspacePool))
      await (await import('./publish')).sendLiveTargets(pool, targets)
    })
  }))
}

export async function runListChanged(executor: object, runId: string, previewOnly = false) {
  await changed(executor, `run:${runId}:${previewOnly ? 'reply' : 'state'}`, (db, workspace) => runListTargets(db, workspace, runId, previewOnly))
  // The run's cards in its own bot's chat show its state; a reply preview is not a state change.
  if (!previewOnly) {
    await (await import('./chats')).runBotChatChanged(executor, runId)
    await (await import('./project-map')).projectMapRunChanged(executor, runId)
  }
}
export const issueListChanged = async (executor: object, issueId: string, titleChanged = false) => {
  await changed(executor, `issue:${issueId}:${titleChanged ? 'title' : 'content'}`, (db, workspace) => issueListTargets(db, workspace, issueId, titleChanged))
  await (await import('./project-map')).projectMapIssueChanged(executor, issueId)
}
export const botListChanged = (executor: object, botId: string) => changed(executor, `bot:${botId}`, (db, workspace) => botListTargets(db, workspace, botId))
export const groupListChanged = (executor: object, conversationId: string, removedUserId: string | null = null) => changed(executor, `group:${conversationId}:${removedUserId ?? ''}`, (db, workspace) => groupListTargets(db, workspace, conversationId, removedUserId))
export const groupListReadChanged = (executor: object, conversationId: string, ownerId: string) => changed(executor, `group-read:${conversationId}:${ownerId}`, async (db, workspace) => (await groupListTargets(db, workspace, conversationId)).filter(value => value.scope.ownerId === ownerId))
export const ownerListChanged = (executor: object, ownerId: string, kinds: readonly OwnerListKind[]) => changed(executor, `owner:${ownerId}:${[...kinds].sort().join(',')}`, (_db, workspace) => ownerListTargets(workspace, ownerId, kinds))
export const workspaceListChanged = (executor: object, workspaceId: string, kinds: readonly WorkspaceListKind[]) => changed(executor, `workspace:${workspaceId}:${[...kinds].sort().join(',')}`, (_db, workspace) => workspaceListTargets(workspace, workspaceId, kinds))

/** Personal prefixes and owner profile labels are resolved while reading the
 * list. Refresh only the owner's actual issue scopes, with no issue IDs on the
 * wire, when that persisted display metadata changes. */
export const ownerIssueListsChanged = (executor: object, ownerId: string) => changed(executor, `owner-issues:${ownerId}`, async (database, workspace) => {
  const { rows: tasks } = await database.query<{ workspaceId: string }>(`SELECT DISTINCT "workspaceId" FROM issues WHERE "userId"=$1 AND "ownershipState"='bound'`, [ownerId])
  const { rows: scopes } = tasks.length ? await workspace.query<LiveScope>(`SELECT DISTINCT m."userId" AS "ownerId",w.id AS "workspaceId"
    FROM mikka_workspaces w
    JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m.status='active'
    WHERE w.id=ANY($1::uuid[])`, [tasks.map(task => task.workspaceId)]) : { rows: [] }
  const home = await ownerLiveScope(workspace, ownerId)
  return mergeTargets([...scopes, ...(home ? [home] : [])].map(scope => target(scope, ['issue_list'])))
})

/** A profile update can change a member avatar in settings and issue rows.
 * Membership comes from the workspace database; content still needs its own
 * ordinary authorized read after this no-content list invalidation. */
export const ownerProfileListsChanged = (executor: object, ownerId: string) => changed(executor, `owner-profile:${ownerId}`, async (_database, workspace) => {
  const { rows: scopes } = await workspace.query<LiveScope>(`SELECT DISTINCT audience."userId" AS "ownerId",w.id AS "workspaceId"
    FROM mikka_workspaces w JOIN mikka_workspace_members source ON source."workspaceId"=w.id AND source."userId"=$1 AND source.status='active'
    JOIN mikka_workspace_members audience ON audience."workspaceId"=w.id AND audience.status='active'`, [ownerId])
  return mergeTargets(scopes.map(scope => target(scope, ['workspace_settings', 'issue_list'])))
})

/**
 * 模型与订阅 changed for an account: a subscription connected, paused or removed, its allowance or model list read
 * again, its order changed. Only the two settings sections listen (`model_settings`), never the app-wide preloader.
 * The account itself re-reads in every workspace it is an active member of (its subscriptions are its own there);
 * teammates only where it shares them with other members (othersMayUse). No connection, model or quota crosses.
 */
export async function ownerSettingsTargets(database: Database, workspaceDatabase: Database, ownerId: string): Promise<Target[]> {
  const { rows: memberships } = await workspaceDatabase.query<{ workspaceId: string }>(`SELECT "workspaceId" FROM mikka_workspace_members WHERE "userId"=$1 AND status='active'`, [ownerId])
  const { othersMayUse } = await import('../personal-policy')
  const shared: string[] = []
  for (const { workspaceId } of memberships) if (await othersMayUse(database, ownerId, workspaceId)) shared.push(workspaceId)
  const { rows: teammates } = shared.length
    ? await workspaceDatabase.query<LiveScope>(`SELECT "userId" AS "ownerId","workspaceId" FROM mikka_workspace_members WHERE "workspaceId"=ANY($1::uuid[]) AND status='active' AND "userId"<>$2`, [shared, ownerId])
    : { rows: [] as LiveScope[] }
  return mergeTargets([...memberships.map(({ workspaceId }) => ({ ownerId, workspaceId })), ...teammates].map(scope => target(scope, ['model_settings'])))
}
/** Best effort: an action that already succeeded never fails on its invalidation (the page's own response updates it). */
export const ownerSettingsChanged = (executor: object, ownerId: string) => changed(executor, `owner-settings:${ownerId}`, (database, workspace) => ownerSettingsTargets(database, workspace, ownerId))
  .catch(() => console.warn('[live] settings invalidation unavailable'))

/** The account's workspace directory and personal issue identifiers are read
 * across selected workspaces. Their transport still uses the actual owned
 * home, and carries only that known list key. */
export const ownerWorkspaceListsChanged = (executor: object, ownerId: string, kinds: readonly ('workspace_settings' | 'issue_list')[]) => changed(executor, `owner-workspaces:${ownerId}:${[...kinds].sort().join(',')}`, async (_db, workspace) => {
  const scope = await ownerLiveScope(workspace, ownerId)
  return scope ? [target(scope, kinds)] : []
})

/** Capture only actual active members through the writer's locked workspace
 * transaction. A removed member may clear this known list after COMMIT; this
 * snapshot never grants a ticket or authorizes a subsequent content read. */
export async function workspaceListScopesBeforeChange(executor: Pick<typeof workspaceDb, 'execute'>, workspaceId: string): Promise<LiveScope[]> {
  if (!liveGatewayConfig(process.env)) return []
  const { rows } = await executor.execute<LiveScope>(sql`SELECT m."userId" AS "ownerId",w.id AS "workspaceId" FROM mikka_workspaces w
    JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m.status='active'
    WHERE w.id=${workspaceId} AND (w.kind='team' OR w."userId"=m."userId")`)
  return rows
}

/** Membership or deletion clears old workspace lists, then refreshes each
 * affected account's workspace directory at its still-authorized real home. */
export const workspaceListScopeChanged = (executor: object, workspaceId: string, previous: readonly LiveScope[]) => changed(executor, `workspace-scope:${workspaceId}`, async (_db, workspace) => {
  const current = await workspaceScopes(workspace, workspaceId)
  const scopes = [...previous.filter(scope => scope.workspaceId === workspaceId), ...current]
  const targets = scopes.map(scope => target(scope, ['workspace_settings', 'issue_list', 'bot_list', 'group_list']))
  for (const ownerId of new Set(scopes.map(scope => scope.ownerId))) {
    const home = await ownerLiveScope(workspace, ownerId)
    if (home) targets.push(target(home, ['workspace_settings', 'bot_chat_list', 'task_run_list', 'thread_list']))
  }
  return mergeTargets(targets)
})

/** Called with the actual locked issue before its scope changes. */
export async function issueListScopesBeforeChange(issue: IssueScope): Promise<LiveScope[]> {
  if (!liveGatewayConfig(process.env)) return []
  try {
    const { workspacePool } = await import('../workspace-db')
    return await issueListScopes(workspacePool, issue)
  } catch {
    console.warn('[live] list scope capture unavailable')
    return []
  }
}

/** Old list and citation previews must clear after the same durable scope
 * transition. They receive only their own known list key, never an issue ID. */
export const issueListScopeChanged = (executor: object, issueId: string, previous: readonly LiveScope[]) => changed(executor, `issue-scope:${issueId}`, async (db, workspace) => {
  const current = await issueListTargets(db, workspace, issueId, true)
  const { rows } = previous.length ? await workspace.query<LiveScope>(
    `SELECT s."ownerId",s."workspaceId" FROM jsonb_to_recordset($1::jsonb) AS s("ownerId" text,"workspaceId" uuid)
      JOIN mikka_workspaces w ON w.id=s."workspaceId"
      JOIN mikka_workspace_members m ON m."workspaceId"=s."workspaceId" AND m."userId"=s."ownerId" AND m.status='active'`, [JSON.stringify(previous)]) : { rows: [] }
  const targets = [...current, ...rows.map(scope => target(scope, ['issue_list']))]
  // A former workspace member may still need to clear their own chat preview.
  // Home membership is checked afresh and no former workspace/entity is sent.
  for (const ownerId of new Set(previous.map(scope => scope.ownerId))) targets.push(...await ownerListTargets(workspace, ownerId, ['bot_chat_list']))
  return mergeTargets(targets)
})

import type { PoolClient } from 'pg'
import type { LiveScope } from './scope'
import { readBatchOwnerScope } from '../desktop-rpc/read-batch-context'

type Database = Pick<PoolClient, 'query'>

/** Owner-wide reads use the owner's real personal workspace as their private
 * transport. This never creates a workspace, borrows a selected team, or grants
 * access to any content. The ordinary reader still authorizes every request. */
export async function ownerLiveScope(workspaceDatabase: Database, ownerId: string): Promise<LiveScope | null> {
  const { rows } = await workspaceDatabase.query<LiveScope>(
    `SELECT w."userId" AS "ownerId",w.id AS "workspaceId" FROM mikka_workspaces w
      JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m."userId"=w."userId" AND m.status='active'
      WHERE w."userId"=$1 AND w.kind='personal'`, [ownerId],
  )
  return rows.length === 1 ? rows[0] : null
}

/** Only a list's read-before-data path may share this observation. Writers and
 * after-COMMIT notification targets always use the fresh reader above. */
export function ownerLiveReadScope(workspaceDatabase: Database, ownerId: string): Promise<LiveScope | null> {
  return readBatchOwnerScope(workspaceDatabase, ownerId, () => ownerLiveScope(workspaceDatabase, ownerId))
}

import type { PoolClient } from 'pg'
import { afterDatabaseCommit, databaseCommitScope } from '../db/commit-effects'
import { LIVE_ID, type LiveInvalidation } from './events'
import { liveGatewayConfig, type LiveScope } from './scope'
import { batchStreamInvalidation } from './stream-batch'
import { wakeTokens, wakeWorkflowAfterCommit } from '../workflow-wake'
import { armDueTimerAfterCommit } from '../due-timer'

type Database = Pick<PoolClient, 'query'>
type Source = { id: string; userId: string; issueId: string | null; botId: string | null; scope: string | null; workspaceId: string | null }
export type ThreadLiveReference = { id: string; workspaceId: string | null }

/** Resolve persisted entity scopes in the workspace DB. Its active membership
 * check is the ticket's check; never infer a scope from the page's selection. */
async function sourceScopes(workspaceDatabase: Database, sources: Source[]): Promise<Map<string, LiveScope>> {
  if (!sources.length) return new Map()
  const { rows } = await workspaceDatabase.query<{ id: string; ownerId: string; workspaceId: string }>(
    `SELECT s.id,s."userId" AS "ownerId",w.id AS "workspaceId"
     FROM jsonb_to_recordset($1::jsonb) AS s(id uuid,"userId" text,"issueId" uuid,"botId" uuid,scope text,"workspaceId" uuid)
     JOIN mikka_workspaces w ON w.id=s."workspaceId"
     JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m."userId"=s."userId" AND m.status='active'
     WHERE w.kind='team' OR w."userId"=s."userId"`,
    [JSON.stringify(sources)],
  )
  return new Map(rows.map(row => [row.id, { ownerId: row.ownerId, workspaceId: row.workspaceId }]))
}

export async function threadLiveReferences(database: Database, workspaceDatabase: Database, runIds: string[], ownerId: string): Promise<ThreadLiveReference[]> {
  if (!runIds.length) return []
  const { rows } = await database.query<Source>(
    `SELECT r.id,r."userId",r."issueId",b.id AS "botId",i.scope,r."workspaceId" FROM agent_runs r
     LEFT JOIN issues i ON i.id=r."issueId"
     LEFT JOIN bots b ON b.id=coalesce(
       (SELECT owned.id FROM computer_run_bindings crb JOIN bots owned ON owned.id=crb."botId" AND owned."ownerId"=crb."ownerId"
         WHERE crb."runId"=r.id AND crb."ownerId"=r."userId"),
       (SELECT owned.id FROM bots owned WHERE owned.id=r."botId" AND owned."ownerId"=r."userId"),
       (SELECT owned.id FROM bot_cloud_runtimes runtime JOIN bots owned ON owned.id=runtime."botId" AND owned."ownerId"=runtime."ownerId"
         WHERE runtime."agentId"=r."agentId" AND runtime."ownerId"=r."userId" LIMIT 1))
     WHERE r.id=ANY($1::uuid[]) AND r."userId"=$2
       AND (r."issueId" IS NULL OR i."ownershipState"='bound')
       AND r."workspaceId" IS NOT NULL
       AND (r."issueId" IS NULL OR i."workspaceId"=r."workspaceId")
       AND (b."workspaceId" IS NULL OR r."workspaceId"=b."workspaceId")
       AND (r."botId" IS NULL OR b.id IS NOT NULL)`, [runIds, ownerId],
  )
  const scopes = await sourceScopes(workspaceDatabase, rows)
  return runIds.map(id => ({ id, workspaceId: scopes.get(id)?.workspaceId ?? null }))
}

/** Body visibility follows issueVisibilityPredicate: a personal body's owner,
 * or active members of the linked workspace. Legacy invitations grant nothing. */
export async function documentLiveTargets(database: Database, workspaceDatabase: Database, issueId: string, viewerId: string | null = null) {
  const { rows: [issue] } = await database.query<{ userId: string; scope: string; workspaceId: string | null }>(
    `SELECT "userId",scope,"workspaceId" FROM issues WHERE id=$1 AND "ownershipState"='bound'
       AND coalesce(content->'attrs'->'mikka',content->'attrs'->'orvilo')->>'deletedAt' IS NULL`, [issueId],
  )
  if (!issue) return []
  const scopes = await documentScopes(workspaceDatabase, issueId, issue, viewerId)
  return scopes.map(scope => ({ scope, events: [{ kind: 'issue_document', id: issueId }] as LiveInvalidation[] }))
}

async function documentScopes(workspaceDatabase: Database, issueId: string, issue: { userId: string; scope: string; workspaceId: string | null }, viewerId: string | null = null) {
  const { rows } = await workspaceDatabase.query<LiveScope>(
    `SELECT m."userId" AS "ownerId",w.id AS "workspaceId" FROM mikka_workspaces w
     JOIN mikka_workspace_members m ON m."workspaceId"=w.id AND m.status='active'
     WHERE w.id=$1 AND (w.kind='team' OR w."userId"=m."userId")
       AND ($2::text IS NULL OR m."userId"=$2)`, [issue.workspaceId, viewerId],
  )
  return rows
}

/** Called after the action's ordinary task authorization, without sending content. */
export async function documentLiveWorkspace(database: Database, workspaceDatabase: Database, issueId: string, viewerId: string) {
  const targets = await documentLiveTargets(database, workspaceDatabase, issueId, viewerId)
  return targets.find(target => target.scope.ownerId === viewerId)?.scope.workspaceId ?? null
}

export async function runLiveTargets(database: Database, workspaceDatabase: Database, runId: string, kind: 'run' | 'thread') {
  const { rows: [run] } = await database.query<{ userId: string; issueId: string | null; retryOf: string | null; continuesRunId: string | null; origin: string | null }>(
    `SELECT "userId","issueId","retryOf","continuesRunId","questionContinuation"->>'originRunId' AS origin FROM agent_runs WHERE id=$1`, [runId],
  )
  if (!run) return []
  const ids = [runId]
  if (kind === 'run') {
    const parents = [run.retryOf, run.continuesRunId, run.origin].filter((id): id is string => typeof id === 'string' && LIVE_ID.test(id))
    if (parents.length) {
      const { rows } = await database.query<{ id: string }>('SELECT id FROM agent_runs WHERE id=ANY($1::uuid[]) AND "userId"=$2 AND "issueId" IS NOT DISTINCT FROM $3::uuid', [parents, run.userId, run.issueId])
      ids.push(...rows.map(row => row.id))
    }
  }
  const references = await threadLiveReferences(database, workspaceDatabase, [...new Set(ids)], run.userId)
  const targets = new Map<string, { scope: LiveScope; events: LiveInvalidation[] }>()
  for (const reference of references) {
    if (!reference.workspaceId) continue
    let target = targets.get(reference.workspaceId)
    if (!target) {
      target = { scope: { ownerId: run.userId, workspaceId: reference.workspaceId }, events: [] }
      targets.set(reference.workspaceId, target)
    }
    target.events.push({ kind, id: reference.id })
  }
  return [...targets.values()]
}

/** An issue's thread list includes teammates' threads, so a run change goes to
 * every member who can see the issue, by the same rule as its body, re-checked
 * when sent. The key carries the issue ID only. */
export async function issueThreadTargets(database: Database, workspaceDatabase: Database, issueId: string) {
  const targets = await documentLiveTargets(database, workspaceDatabase, issueId)
  return targets.map(target => ({ scope: target.scope, events: [{ kind: 'issue_threads', id: issueId }] as LiveInvalidation[] }))
}

/** A run's panels (its owner) and its issue's thread list (the issue's members), one request per channel. */
export async function runChangeTargets(database: Database, workspaceDatabase: Database, runId: string) {
  const targets = await runLiveTargets(database, workspaceDatabase, runId, 'run')
  const { rows: [run] } = await database.query<{ issueId: string | null }>('SELECT "issueId" FROM agent_runs WHERE id=$1', [runId])
  const merged = new Map(targets.map(target => [JSON.stringify(target.scope), target]))
  if (run?.issueId) for (const target of await issueThreadTargets(database, workspaceDatabase, run.issueId)) {
    const key = JSON.stringify(target.scope)
    const current = merged.get(key)
    if (current) current.events.push(...target.events); else merged.set(key, target)
  }
  return [...merged.values()]
}

async function changed(executor: object, kind: 'issue_document' | 'run' | 'thread', id: string) {
  if (!liveGatewayConfig(process.env)) return
  const { scheduleLive } = await import('./notify')
  const databaseScope = databaseCommitScope(executor)
  const publish = async () => {
    const { pool, withoutDatabaseClient } = await import('../db/request-scope')
    const { workspacePool } = await import('../workspace-db')
    await withoutDatabaseClient(async () => {
      const targets = kind === 'issue_document' ? await documentLiveTargets(pool, workspacePool, id)
        : kind === 'run' ? await runChangeTargets(pool, workspacePool, id)
        : await runLiveTargets(pool, workspacePool, id, kind)
      await (await import('./publish')).sendLiveTargets(pool, targets)
    })
  }
  afterDatabaseCommit(executor, `${kind}:${id}`, () => scheduleLive(() => kind === 'thread'
    ? batchStreamInvalidation(databaseScope, id, publish)
    : publish()))
}

export const documentChanged = (executor: object, issueId: string) => {
  armDueTimerAfterCommit(executor, 'run-recovery')
  return changed(executor, 'issue_document', issueId)
}
/** A semantic run write also wakes the already mounted immediate parent of a new continuation,
 * and its issue's thread list for every member who can see the issue. */
export const runChanged = (executor: object, runId: string) => {
  // A cloud run's thread-machine lifecycle waits on this instead of re-reading every 30 s (#1212).
  wakeWorkflowAfterCommit(executor, wakeTokens.threadMachine(runId))
  armDueTimerAfterCommit(executor, 'run-recovery')
  return changed(executor, 'run', runId)
}
/** Stream chunks use a separate key so one final state change need not wait for the text cadence. */
export const threadChanged = (executor: object, runId: string) => changed(executor, 'thread', runId)

/** Capture only from the writer's locked issue, before its scope changes. An
 * invalidation contains the already-known ID, never the old or new body. */
export async function documentScopesBeforeChange(issue: { id: string; userId: string; scope: string; workspaceId: string | null }): Promise<LiveScope[]> {
  if (!liveGatewayConfig(process.env)) return []
  try {
    const { workspacePool } = await import('../workspace-db')
    return await documentScopes(workspacePool, issue.id, issue)
  } catch {
    console.warn('[live] document scope capture unavailable')
    return []
  }
}

/** Old subscriptions must reauthorize and move to the new canonical channel.
 * Membership is rechecked after COMMIT, including for previously allowed keys. */
export async function documentScopeChanged(executor: object, issueId: string, previous: LiveScope[]) {
  if (!liveGatewayConfig(process.env)) return
  const { scheduleLive, sendLiveInvalidations } = await import('./notify')
  afterDatabaseCommit(executor, `issue-scope:${issueId}`, () => scheduleLive(async () => {
    const { pool, withoutDatabaseClient } = await import('../db/request-scope')
    const { workspacePool } = await import('../workspace-db')
    await withoutDatabaseClient(async () => {
      const current = await documentLiveTargets(pool, workspacePool, issueId)
      const { rows } = previous.length ? await workspacePool.query<LiveScope>(
        `SELECT s."ownerId",s."workspaceId" FROM jsonb_to_recordset($1::jsonb) AS s("ownerId" text,"workspaceId" uuid)
          JOIN mikka_workspaces w ON w.id=s."workspaceId"
          JOIN mikka_workspace_members m ON m."workspaceId"=s."workspaceId" AND m."userId"=s."ownerId" AND m.status='active'`, [JSON.stringify(previous)]) : { rows: [] }
      const scopes = new Map([...rows, ...current.map(target => target.scope)].map(scope => [JSON.stringify(scope), scope]))
      await Promise.all([...scopes.values()].map(scope => sendLiveInvalidations(scope, [
        { kind: 'issue_document', id: issueId }, { kind: 'factory_issue', id: issueId },
      ])))
    })
  }))
}

import type { PoolClient } from 'pg'
import { isLiveRevisionKind, liveRevision, LIVE_ID, type LiveInvalidation, type LiveKind } from './events'

type Database = Pick<PoolClient, 'query'>
export type LiveRef = { kind: LiveKind; id: string }
/** `${kind}:${id}` → the revision a read saw before reading its data. */
export type LiveRevisions = Record<string, number>
export const liveRevisionKey = (kind: LiveKind, id: string) => `${kind}:${id}`

const refs = (values: readonly LiveRef[]) => {
  const unique = new Map<string, LiveRef>()
  for (const value of values) if (isLiveRevisionKind(value.kind) && LIVE_ID.test(value.id)) unique.set(liveRevisionKey(value.kind, value.id.toLowerCase()), { kind: value.kind, id: value.id.toLowerCase() })
  return [...unique.values()].sort((a, b) => a.kind.localeCompare(b.kind) || a.id.localeCompare(b.id))
}

/**
 * Raise each key's counter once, after its change has committed and before its
 * push is sent. A reader reads the counter before its data, so data read at
 * revision R contains every change whose push carries R or less. A value the
 * writer assigned inside its transaction (a sequence, `now()`) could commit out
 * of order and would let a newer reader skip a change it never saw.
 *
 * One autocommitted statement in key order: no lock outlives it, and two
 * publishers cannot deadlock.
 */
export async function bumpLiveRevisions(database: Database, values: readonly LiveRef[]): Promise<LiveRevisions> {
  const keys = refs(values)
  if (!keys.length) return {}
  const { rows } = await database.query<{ kind: LiveKind; id: string; revision: string }>(
    `INSERT INTO live_revisions (kind, id)
      SELECT k, i FROM unnest($1::text[], $2::uuid[]) AS t(k, i) ORDER BY k, i
      ON CONFLICT (kind, id) DO UPDATE SET revision = live_revisions.revision + 1
      RETURNING kind, id::text AS id, revision`, [keys.map(key => key.kind), keys.map(key => key.id)])
  return Object.fromEntries(rows.map(row => [liveRevisionKey(row.kind, row.id), Number(row.revision)]))
}

/** The counters for these keys, read before the data they describe. A key never raised is absent (always read). */
export async function readLiveRevisions(database: Database, values: readonly LiveRef[]): Promise<LiveRevisions> {
  const keys = refs(values)
  if (!keys.length) return {}
  const { rows } = await database.query<{ kind: LiveKind; id: string; revision: string }>(
    `SELECT r.kind, r.id::text AS id, r.revision FROM live_revisions r
      JOIN unnest($1::text[], $2::uuid[]) AS t(k, i) ON r.kind = t.k AND r.id = t.i`, [keys.map(key => key.kind), keys.map(key => key.id)])
  return Object.fromEntries(rows.map(row => [liveRevisionKey(row.kind, row.id), Number(row.revision)])
    .filter(([, revision]) => Number.isSafeInteger(revision) && (revision as number) > 0))
}

export function withLiveRevisions(events: readonly LiveInvalidation[], revisions: LiveRevisions): LiveInvalidation[] {
  return events.map(event => {
    const rev = revisions[liveRevisionKey(event.kind, event.id.toLowerCase())]
    return rev ? { kind: event.kind, id: event.id, rev } : { kind: event.kind, id: event.id }
  })
}

/** The client side: the held revision of one entity in a read's `live.revisions`. */
export function heldRevision(read: { live?: { revisions?: LiveRevisions } } | undefined | null, kind: LiveKind, id: string | null | undefined): number | undefined {
  if (!id) return undefined
  const value = read?.live?.revisions?.[liveRevisionKey(kind, id.toLowerCase())]
  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0 ? value : undefined
}

/** A shared snapshot may satisfy a push only when it proves every required revision. */
export function coversLiveRevisions(read: unknown, required?: Readonly<LiveRevisions>): boolean {
  const revisions = (read as { live?: { revisions?: Readonly<Record<string, unknown>> } } | null)?.live?.revisions
  return Object.entries(required ?? {}).every(([key, revision]) => {
    const held = revisions?.[key]
    return liveRevision(held) && held >= revision
  })
}

const LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost', '[::1]', '::1'])

/** A loopback host as `URL.hostname` gives it (`[::1]`), or with the IPv6 brackets stripped (`::1`). */
export function isLoopbackHost(hostname: string): boolean {
  return LOOPBACK_HOSTS.has(hostname)
}

/**
 * 「模型与订阅」: the API key providers a person can add, and the shape the
 * page, the model picker and the run injection share (orchestration.md § 1,
 * § 3, § 6). An Agent talks one protocol: Claude Code the Anthropic one, Codex
 * the OpenAI one. A preset provider serves every protocol its official API
 * speaks (DeepSeek and Kimi speak both, so one key runs on both Agents; Alex,
 * 2026-11-02); a custom provider serves the one protocol the person picked.
 */
export const API_KEY_PRESETS = ['anthropic', 'openai', 'deepseek', 'kimi'] as const
export type ApiKeyPreset = (typeof API_KEY_PRESETS)[number]
export type ApiKeyProvider = ApiKeyPreset | 'custom'
export type ApiKeyProtocol = 'anthropic' | 'openai'
export type ApiKeyHarness = 'claude_code' | 'codex'

interface PresetEndpoint {
  /**
   * Per protocol the official API speaks, the base URL its Agent talks to:
   * ANTHROPIC_BASE_URL for Claude Code, the model provider's base_url for
   * Codex (which Mikka runs on the Responses API). Anthropic first.
   */
  endpoints: Partial<Record<ApiKeyProtocol, string>>
  /** The read-only list the key is checked against when it is added. */
  modelsUrl: string
  modelsAuth: ApiKeyProtocol
  /** The OpenAI-compatible chat endpoint a bot chat (Mikka's own harness, R-05) talks to. */
  chatBaseUrl: string
}

export const API_KEY_PRESET_ENDPOINTS: Record<ApiKeyPreset, PresetEndpoint> = {
  anthropic: { endpoints: { anthropic: 'https://api.anthropic.com' }, modelsUrl: 'https://api.anthropic.com/v1/models?limit=1000', modelsAuth: 'anthropic', chatBaseUrl: 'https://api.anthropic.com/v1' },
  openai: { endpoints: { openai: 'https://api.openai.com/v1' }, modelsUrl: 'https://api.openai.com/v1/models', modelsAuth: 'openai', chatBaseUrl: 'https://api.openai.com/v1' },
  // Both formats, from the providers' own docs: api-docs.deepseek.com (base_url OpenAI / Anthropic) and
  // platform.kimi.ai/docs/api/overview (OpenAI Chat Completions and Responses at /v1, Anthropic Messages at /anthropic).
  deepseek: { endpoints: { anthropic: 'https://api.deepseek.com/anthropic', openai: 'https://api.deepseek.com/v1' }, modelsUrl: 'https://api.deepseek.com/models', modelsAuth: 'openai', chatBaseUrl: 'https://api.deepseek.com/v1' },
  kimi: { endpoints: { anthropic: 'https://api.moonshot.cn/anthropic', openai: 'https://api.moonshot.cn/v1' }, modelsUrl: 'https://api.moonshot.cn/v1/models', modelsAuth: 'openai', chatBaseUrl: 'https://api.moonshot.cn/v1' },
}

/** The models list a custom provider is checked against, by its protocol. */
export function customModelsUrl(baseUrl: string, protocol: ApiKeyProtocol): string {
  const base = baseUrl.replace(/\/+$/, '')
  return protocol === 'anthropic' ? `${base}/v1/models` : `${base}/models`
}

/**
 * Where a bot chat reaches a key's models: the preset's OpenAI-compatible
 * endpoint, or a custom provider's base URL when it speaks the OpenAI protocol.
 * An Anthropic-only custom provider serves threads (Claude Code) but not bot chats.
 */
export function apiKeyChatBaseUrl(key: Pick<ApiKeyView, 'provider' | 'baseUrl' | 'protocol'>): string | null {
  if (key.provider !== 'custom') return API_KEY_PRESET_ENDPOINTS[key.provider].chatBaseUrl
  return key.protocol === 'openai' ? key.baseUrl : null
}

/** The Agent that speaks a protocol: Codex the OpenAI one, Claude Code the Anthropic one (§ 3). */
export const protocolHarness = (protocol: ApiKeyProtocol): ApiKeyHarness => protocol === 'openai' ? 'codex' : 'claude_code'

/** The protocols a key serves: every one its preset's API speaks, or the custom provider's one. Anthropic first. */
export function apiKeyProtocols(key: Pick<ApiKeyView, 'provider' | 'protocol'>): ApiKeyProtocol[] {
  if (key.provider === 'custom') return [key.protocol]
  const endpoints = API_KEY_PRESET_ENDPOINTS[key.provider].endpoints
  return (['anthropic', 'openai'] as const).filter(protocol => endpoints[protocol])
}

/** The key fields that decide which Agents it serves. */
export type ApiKeyAgentFields = Pick<ApiKeyView, 'provider' | 'protocol' | 'responsesApi'>

/**
 * The protocols an Agent can run a key on: Codex runs on the Responses API
 * only, so an OpenAI-protocol custom provider without it serves bot chats
 * (Chat Completions) but not Codex.
 */
const agentProtocols = (key: ApiKeyAgentFields) => apiKeyProtocols(key).filter(protocol => protocol !== 'openai' || key.responsesApi)

/** The Agents that can run a key's models (Claude Code first). */
export const apiKeyHarnesses = (key: ApiKeyAgentFields): ApiKeyHarness[] => agentProtocols(key).map(protocolHarness)

/** What one Agent talks to with this key, or null when the key does not serve that Agent. */
export function apiKeyEndpoint(key: ApiKeyAgentFields & Pick<ApiKeyView, 'baseUrl'>, harness: ApiKeyHarness): { protocol: ApiKeyProtocol; baseUrl: string } | null {
  const protocol = agentProtocols(key).find(item => protocolHarness(item) === harness)
  if (!protocol) return null
  const baseUrl = key.provider === 'custom' ? key.baseUrl : API_KEY_PRESET_ENDPOINTS[key.provider].endpoints[protocol]
  return baseUrl ? { protocol, baseUrl } : null
}

/** One credential row as the page and the model picker read it. Never the key itself. */
export interface ApiKeyView {
  id: string
  provider: ApiKeyProvider
  /** A custom provider's own name; null for the presets. */
  name: string | null
  baseUrl: string | null
  /** A custom provider's protocol. A preset's is stored but not used: it serves `apiKeyProtocols`. */
  protocol: ApiKeyProtocol
  /** The key's last four characters. */
  last4: string
  /** What the provider's /models last answered; never a list written by Mikka. */
  models: string[]
  /** Why the last 重新获取模型 failed (401/403, or anything else); null after a good answer. */
  modelsError: 'invalid' | 'unavailable' | null
  /** Whether the OpenAI endpoint serves the Responses API, which Codex runs on. Probed for custom providers only; presets serve it. */
  responsesApi: boolean
}

import { modelEnabled, type ModelSettings } from './enabled-models-policy'
import 'server-only'
import { executionMembersActive, revalidateExecutionIdentity, ExecutionIdentityError } from './execution-identity'
import type { WorkerDefinitionSnapshot } from './agent-kit/worker'
import { randomUUID } from 'node:crypto'
import { lookup } from 'node:dns/promises'
import { isIP } from 'node:net'
import type { Pool, PoolClient } from 'pg'
import { z } from 'zod'
import { isPrivateAddress } from '@/lib/link-preview-parse'
import { isLoopbackHost } from '@/lib/loopback'
