import { SpanStatusCode, context, isSpanContextValid, trace, type Span } from '@opentelemetry/api'
import { routeScope } from './labels'
import { safeErrorAttributes } from '@mikka/protocol/tracing'

// Background work as its own labelled job (docs/operations/tracing.md,
// "Background work"). Only @opentelemetry/api: without a registered tracer
// (tests, CI, a sample rate of 0) the spans are no-ops and only the label
// (which the db_sample log line also reads) remains.

export type JobKind = 'background' | 'workflow' | 'cron'
export type JobOptions = {
  /**
   * A deferred operation has its own lifetime and route label. Its parent may
   * already have ended; W3C ancestry still joins the same end-to-end trace.
   */
  detach?: boolean
}

const isThenable = (value: unknown): value is PromiseLike<unknown> => typeof (value as { then?: unknown } | null)?.then === 'function'

/**
 * Runs `work` under the job's label: a span named `route` with
 * `mikka.route=route` and `mikka.client_kind=kind`, and the same label in the
 * route scope, so every query inside it (and any db_sample line) carries the
 * job's route rather than the caller's.
 *
 * The span retains its scheduling parent even after that parent ends. A job
 * with no valid context creates a root. Its independent route label keeps
 * database attribution correct without splitting the run into several traces.
 */
export function runJob<T>(route: string, kind: JobKind, work: () => T, _options: JobOptions = {}): T {
  let span: Span | undefined
  let scope = context.active()
  try {
    const active = trace.getSpan(scope)
    const from = active?.spanContext()
    span = trace.getTracer('mikka.jobs').startSpan(route, { root: !from || !isSpanContextValid(from), attributes: { 'mikka.route': route, 'mikka.client_kind': kind, 'mikka.trace.critical': kind === 'workflow' || /coordinator|dispatch|run-|factory|computer/.test(route) } }, scope)
    scope = trace.setSpan(scope, span)
  } catch { span = undefined }
  const finish = (failed: boolean, error?: unknown) => {
    try {
      if (failed) {
        span?.setAttributes(safeErrorAttributes(error))
        span?.setStatus({ code: SpanStatusCode.ERROR })
      }
      span?.end()
    } catch { /* tracing never breaks the job */ }
  }
  return context.with(scope, () => routeScope.run(route, () => {
    let result: T
    try { result = work() } catch (error) { finish(true, error); throw error }
    if (!isThenable(result)) { finish(false); return result }
    return Promise.resolve(result).then(value => { finish(false); return value }, (error: unknown) => { finish(true, error); throw error }) as T
  }))
}

import { AsyncLocalStorage } from 'node:async_hooks'

// The `mikka.route` label in force for the code running now
// (docs/operations/tracing.md, "Background work"). Shared by the span
// processor (lib/tracing/spans.ts) and the db_sample log line
// (lib/db/egress-sample.ts). No OpenTelemetry import, so either can load it.

/**
 * The route template, Server Action or background job the current code runs
 * under, set by lib/request-log.ts, withDatabaseOperation and runJob. Shared
 * through a global key, so every bundled copy of these modules sees one store.
 */
export const routeScope: AsyncLocalStorage<string> = ((globalThis as Record<symbol, unknown>)[Symbol.for('mikka.requestRoute')] ??= new AsyncLocalStorage<string>()) as AsyncLocalStorage<string>

type StepContext = { stepMetadata?: { stepName?: unknown }; workflowMetadata?: { workflowName?: unknown } }

/**
 * The Workflow SDK runs every `'use step'` body inside this process-wide
 * AsyncLocalStorage (`@workflow/core` step/context-storage.js; it is what
 * `getStepMetadata()` reads). Reading it here labels all steps without
 * touching each one.
 */
const STEP_CONTEXT = Symbol.for('WORKFLOW_STEP_CONTEXT_STORAGE')

/** `step//./workflows/run-publication/steps//publishResult` → `publishResult`. Identifier characters only. */
export function shortName(name: unknown): string | undefined {
  if (typeof name !== 'string' || !name) return undefined
  const short = (name.split('//').at(-1) ?? '').split('/').at(-1)?.replace(/[^A-Za-z0-9_.-]/g, '')
  return short?.slice(0, 128) || undefined
}

/** `workflow:<workflow>/<step>` while a Workflow step body runs, else undefined. */
export function workflowStepRoute(): string | undefined {
  try {
    const store = ((globalThis as Record<symbol, unknown>)[STEP_CONTEXT] as AsyncLocalStorage<StepContext> | undefined)?.getStore()
    const step = shortName(store?.stepMetadata?.stepName)
    return step ? `workflow:${shortName(store?.workflowMetadata?.workflowName) ?? 'unknown'}/${step}` : undefined
  } catch { return undefined }
}

/** The label for a query issued now: the innermost request, action or job label, else the Workflow step. */
export function currentRoute(): string | undefined {
  return routeScope.getStore() ?? workflowStepRoute()
}

/** A workspace rule refused the request; `code` names it for the action's error message. No server imports. */
export class WorkspaceError extends Error {
  constructor(readonly code: string) {
    super(code)
    this.name = 'WorkspaceError'
  }
}

// An error with a stable code for the UI, a detail from a closed set saying
// which precondition failed, and the original error kept as `cause`
// (decision docs/design/decisions/2026-11-05-0330-error-causes.md).
//
// The message is the code, or `code (detail)` when there is a detail, the same
// shape the run's stored error already uses ("… (child_exit: cli_exited_early)").
// The UI reads it back with parseCodedErrorText and shows the copy for it from
// messages/*.json; the raw code goes only into the details area.

export interface CodedErrorOptions<D extends string = string> {
  /** Which precondition failed, from the code's closed set. */
  detail?: D
  /** The error that caused this one. Kept, never shown; logged by name and code only. */
  cause?: unknown
}

const IDENT = /^[a-z][a-z0-9_]*$/

export class CodedError<C extends string = string, D extends string = string> extends Error {
  readonly code: C
  readonly detail?: D
  constructor(code: C, options: CodedErrorOptions<D> = {}) {
    super(options.detail ? `${code} (${options.detail})` : code, options.cause === undefined ? undefined : { cause: options.cause })
    this.name = "CodedError"
    this.code = code
    if (options.detail) this.detail = options.detail
  }
}

/** The first coded error with this code in the error and its cause chain. */
export function findCodedError(error: unknown, code: string, depth = 6): CodedError | undefined {
  for (let value = error, i = 0; value instanceof Error && i < depth; i++, value = value.cause)
    if (value instanceof CodedError && value.code === code) return value
  return undefined
}

/** The stored text of a coded error read back: `code` or `code (detail)`; null for any other text. */
export function parseCodedErrorText(text: string | null | undefined): { code: string; detail: string | null } | null {
  const line = text?.trim()
  if (!line) return null
  const match = /^([a-z][a-z0-9_]*)(?: \(([a-z][a-z0-9_]*)\))?$/.exec(line)
  return match ? { code: match[1], detail: match[2] ?? null } : null
}

export interface CauseField {
  name: string
  code?: string | number
  detail?: string
}

const SAFE_CODE = /^[A-Za-z0-9_.:-]{1,64}$/

/**
 * The cause chain by name and code only, outermost first. Never the message:
 * it can carry stderr, a response body or a credential.
 */
export function causeFields(cause: unknown, depth = 4): CauseField[] {
  const out: CauseField[] = []
  for (let value = cause, i = 0; value !== undefined && value !== null && i < depth; i++) {
    if (typeof value !== "object") { out.push({ name: typeof value }); break }
    const record = value as { name?: unknown; code?: unknown; detail?: unknown; cause?: unknown; constructor?: { name?: unknown } }
    const name = typeof record.name === "string" && SAFE_CODE.test(record.name) ? record.name
      : typeof record.constructor?.name === "string" && SAFE_CODE.test(record.constructor.name) ? record.constructor.name : "unknown"
    const field: CauseField = { name }
    if ((typeof record.code === "string" && SAFE_CODE.test(record.code)) || (typeof record.code === "number" && Number.isFinite(record.code))) field.code = record.code as string | number
    if (typeof record.detail === "string" && IDENT.test(record.detail)) field.detail = record.detail
    out.push(field)
    if (value instanceof AggregateError) {
      for (const inner of value.errors.slice(0, 3)) out.push(...causeFields(inner, 1).map(item => ({ ...item, name: `aggregate:${item.name}` })))
    }
    value = record.cause
  }
  return out
}

export interface CodedErrorLog {
  warn(fields: Record<string, unknown>, message?: string): void
}

/** A JSON line on stderr, the shape the web's request log uses; for code without a logger. */
export const consoleCodedErrorLog: CodedErrorLog = {
  warn(fields, message) {
    console.warn(JSON.stringify({ level: "warn", msg: message ?? "coded_error", ...fields }))
  },
}

/**
 * One structured line for a coded error: its code, detail and the cause chain
 * by name and code. `fields` must be identifiers (run id, harness), never
 * free text.
 */
export function logCodedError(error: CodedError, fields: Record<string, string | number | boolean | undefined> = {}, log: CodedErrorLog = consoleCodedErrorLog) {
  try {
    log.warn({ event: "coded_error", code: error.code, ...(error.detail ? { detail: error.detail } : {}), causes: causeFields(error.cause), ...fields }, error.code)
  } catch { /* Logging never replaces the error itself. */ }
}

import { causeFields } from "./coded-error.ts"

// Span privacy rules shared by the web server (lib/tracing/sanitize.ts) and
// the daemon (packages/daemon/src/tracing.ts). docs/operations/tracing.md, "Privacy".

const STRING_LIMIT = 256
const EMAIL = /[^\s@"'<>(),;:]+@[^\s@"'<>(),;:]+\.[A-Za-z]{2,}/g
const IPV4 = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g
const IPV6 = /\b(?:[0-9a-f]{1,4}:){7}[0-9a-f]{1,4}\b|\b(?:[0-9a-f]{1,4}:){1,6}:(?:[0-9a-f]{1,4}(?::[0-9a-f]{1,4})*)?\b/gi

/** Removes `?query` and `#hash` from any URL or path inside the string, then masks emails and IPs. */
export function scrubString(value: string): string {
  const scrubbed = value
    .replace(/(\b[a-z][a-z0-9+.-]*:\/\/[^\s?#]*|(?:^|(?<=\s))\/[^\s?#]*)[?#]\S*/gi, '$1')
    .replace(EMAIL, '[email]')
    .replace(IPV4, '[ip]')
    .replace(IPV6, '[ip]')
  return scrubbed.length > STRING_LIMIT ? scrubbed.slice(0, STRING_LIMIT) : scrubbed
}

const HOME_PATH = /(?:~|\/Users\/[^/\s]+|\/home\/[^/\s]+|\/root|[A-Za-z]:\\Users\\[^\\\s]+)(?=[/\\\s]|$)[^\s]*/g

/** A string from the user's computer: `scrubString`, and any path under a home directory becomes `[home]`. */
export function scrubLocalString(value: string): string {
  return scrubString(value.replace(HOME_PATH, '[home]'))
}

/** Only identifiers become codes: a message, path or token never matches. */
const CODE = /^[a-z][a-z0-9_]{0,63}$/i

export type ErrorAttributes = { "error.type": string; "mikka.error.code"?: string; "mikka.error.detail"?: string; "mikka.error.causes"?: string }

/**
 * A failed operation's error by name and code only, read from the error and
 * its cause chain (CodedError, a refusal with `code`). Never the message: it
 * can echo user input, stderr or a credential.
 */
export function safeErrorAttributes(error: unknown): ErrorAttributes {
  let chain: ReturnType<typeof causeFields>
  try {
    chain = causeFields(error)
  } catch {
    // Provider errors can expose throwing getters. Diagnostics must preserve
    // the original failure, never export or throw a new inspection error.
    return { "error.type": "unknown" }
  }
  const coded = chain.find(field => typeof field.code === "string" && CODE.test(field.code))
  return {
    "error.type": chain[0]?.name ?? "unknown",
    ...(coded ? { "mikka.error.code": String(coded.code) } : {}),
    ...(coded?.detail ? { "mikka.error.detail": coded.detail } : {}),
    ...(chain.length > 1 ? { "mikka.error.causes": chain.map(field => [field.name, field.code, field.detail].filter(value => value !== undefined).join(':')).join(' > ').slice(0, STRING_LIMIT) } : {}),
  }
}

/** Require an explicit Preview endpoint and password, excluding pg defaults. */
export function previewDatabaseURL(env) {
  const value = env.DATABASE_URL
  if (!value?.trim()) throw new Error('PREVIEW_DATABASE_URL_REQUIRED')
  try {
    if (value !== value.trim()) throw new Error()
    const url = new URL(value)
    const database = decodeURIComponent(url.pathname.slice(1))
    const user = decodeURIComponent(url.username)
    const overrides = ['host', 'hostaddr', 'port', 'dbname', 'database', 'user', 'password']
    if (!['postgres:', 'postgresql:'].includes(url.protocol) || !url.hostname || !user.trim() || !database.trim() || database.includes('/') || url.hash ||
      !url.password ||
      [...url.searchParams.keys()].some(key => overrides.includes(key.toLowerCase()))) throw new Error()
    // pg otherwise takes PGPORT from the surrounding environment when the
    // connection string omits a port, even with an explicit host and database.
    if (!url.port) url.port = '5432'
    return url.href
  } catch { throw new Error('PREVIEW_DATABASE_URL_INVALID') }
}

// Next aliases this marker in server bundles. Node integration tests run only
// on the server; resolve the marker without changing application behavior.
import { registerHooks } from 'node:module'
registerHooks({ resolve(specifier, context, nextResolve) {
  if (specifier === 'server-only') return { url: 'data:text/javascript,export {}', shortCircuit: true }
  return nextResolve(specifier, context)
} })

// Test-only: lets node:test import modules marked `import 'server-only'`.
// Next resolves that package itself; plain node has no copy of it, so map it to an empty module.
import { register } from 'node:module'

register('data:text/javascript,' + encodeURIComponent(`
export async function resolve(specifier, context, next) {
  if (specifier === 'server-only') return { url: 'data:text/javascript,export {}', shortCircuit: true }
  return next(specifier, context)
}`))
